const top_warwick = {
  champion: '워윅',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '가렌은 (P)\'인내심\' 덕분에 잠시 공격을 맞지 않으면 체력을 회복하니 짧게라도 계속 긁어주는 게 좋아요. (Q)\'결정타\'를 맞으면 침묵에 걸려 스킬을 쓸 수 없으니 가렌의 이동 속도가 빨라져 달려들 때 (E)\'원시의 포효\'를 미리 켜 두세요. 1~2레벨에는 (Q)\'야수의 송곳니\'로 적절히 체력을 회복하며 버티는 것에 집중하세요.', lv3: '가렌이 (E)\'심판\'으로 회전하며 다가올 때 (E)\'원시의 포효\'를 재사용해서 공포를 걸어 흐름을 끊으세요. 가렌이 (W)\'용기\'를 사용해 보호막을 켜면 무리하게 딜교환하기보다 (Q)\'야수의 송곳니\'로 거리를 조절하며 기다려요. (Q)\'결정타\'는 침묵을 걸기 때문에 가렌의 이동 속도가 빨라진 순간에는 스킬을 미리 써 두세요.', lv6: '가렌의 (R)\'데마시아의 정의\'는 잃은 체력에 비례해 강해지니 내 체력이 낮을 때는 무리하게 붙지 마세요. 가렌의 체력이 낮을 때 (R)\'무한의 구속\'으로 제압하면 (P)\'끝없는 허기\'와 궁극기의 회복으로 체력을 되찾으며 마무리할 수 있어요. 정글러가 근처에 있을 때 라인을 당겨 두면 이 킬각이 더 확실해져요.', item: '가렌의 물리 피해를 줄여주는 판금 장화와 전투 지속력을 높여주는 몰락한 왕의 검을 추천해요. 몰락한 왕의 검은 전투 중에 계속해서 체력을 회복하는 데 도움을 줘요.', spell: '점멸과 점화를 추천해요. 점화로 가렌의 (P)\'인내심\' 회복을 억제하면 킬을 내기가 훨씬 수월해요.' },
    '갱플랭크': { lv1: '(Q)\'혀어어어업상\'은 대상 지정 스킬이라 미니언 뒤에 숨어도 피할 수 없으니, 맞더라도 (Q)\'야수의 송곳니\'로 빠르게 붙어 평타 교환을 하세요. (P)\'불의 심판\'이 묻은 근접 공격에 오래 노출되지 않도록 짧게 딜교환하고 빠지는 것이 좋아요.', lv3: '(E)\'원시의 포효\'로 피해를 줄이며 진입하고, (E)\'화약통\'이 터져 둔화가 걸리기 전에 빠르게 거리를 좁히세요. (W)\'괴혈병 치료\'는 군중 제어를 제거하므로 이 스킬이 빠진 것을 확인한 뒤에 (E)\'원시의 포효\'의 공포를 걸어야 해요. 그 뒤 (Q)\'야수의 송곳니\'로 물고 늘어지세요.', lv6: '(R)\'무한의 구속\'으로 제압하는 동안에는 (W)\'괴혈병 치료\'를 사용할 수 없으니, (W)\'피의 사냥\'으로 속도를 높여 진입해 묶으세요. (R)\'포탄 세례\'의 둔화 장판을 피해 경로를 잡고, 상대가 (W)\'괴혈병 치료\'를 뺀 시점에 맞춰 공격하세요.', item: '판금 장화는 (P)\'불의 심판\'이 붙은 근접 기본 공격 피해를 줄여 줘요. 삼위일체는 체력과 공격 속도를 제공해 근접전 능력을 높여줘요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'괴혈병 치료\'의 체력 회복을 억제하면 킬각을 잡기 편해요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'로 둔화를 걸며 견제하고, 스킬을 쓰면 (P)\'서비스 시간\'으로 주기적으로 체력을 회복해요. 술통이 터지는 위치를 보고 피하면서 막타를 챙기세요. 1~2레벨 구간에는 (Q)\'야수의 송곳니\'를 활용해 체력을 회복하며 버티는 것이 중요해요.', lv3: '그라가스의 (E)\'몸통 박치기\' 에어본에 맞으면 딜교가 어려워지니 스킬을 빼도록 유도하세요. 그라가스가 (W)\'취중 분노\'를 켜면 받는 피해가 줄어드니 그 지속시간 동안에는 (E)\'원시의 포효\'로 피해를 줄이며 대응하세요. (E)\'몸통 박치기\'가 빠진 타이밍에 (Q)\'야수의 송곳니\'를 맞히면 딜교환을 주도할 수 있어요.', lv6: '(R)\'무한의 구속\'으로 그라가스를 제압할 수 있지만 (R)\'술통 폭발\'은 적을 밀어내니 폭발 범위 안에서 먼저 맞지 않도록 주의하세요. 그라가스의 체력이 낮아 (W)\'피의 사냥\' 효과가 활성화될 때 (R)\'무한의 구속\'을 사용하면 확실하게 압박할 수 있어요. 라인을 너무 밀어두면 정글러가 개입하기 쉬우니 라인 관리에 유의하세요.', item: '몰락한 왕의 검을 첫 코어로 가서 맞딜 능력을 높이세요. 신발은 마법 피해를 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (P)\'서비스 시간\'의 체력 회복 효과를 점화로 억제하여 킬각을 잡기 쉬워져요.' },
    '그웬': { lv1: '1~2레벨에는 그웬의 (Q)\'싹둑싹둑!\' 중첩을 조심하며 무리한 평타 교환은 피하세요. (Q)\'야수의 송곳니\'를 사용해 체력을 회복하며 짧게 딜교환하고, 그웬의 (E)\'돌격가위\' 진입에 맞춰 (E)\'원시의 포효\'를 써서 피해를 줄여야 해요.', lv3: '그웬이 (W)\'신성한 안개\'를 켜면 안개 밖에서는 (Q)\'야수의 송곳니\'로 대상을 지정할 수 없으니 안개 안으로 들어가 물거나 안개가 끝날 때까지 기다리세요. 그웬이 (E)\'돌격가위\'로 거리를 좁히며 들어올 때 (E)\'원시의 포효\'를 재사용해 공포를 맞히는 것이 중요해요. (Q)\'싹둑싹둑!\'의 중앙 고정 피해를 피하기 위해 옆으로 움직이며 싸우세요.', lv6: '(R)\'무한의 구속\'을 적중시키면 제압 상태로 피해를 입히며 체력을 대량으로 회복할 수 있어요. 그웬이 (R)\'바느질\'로 거리를 벌리려 하면 (Q)\'야수의 송곳니\'를 활용해 빠르게 따라붙으세요. 체력이 낮은 적을 발견했을 때 (R)\'무한의 구속\'으로 킬을 노리는 것이 좋아요.', item: '마법 저항력을 제공하는 헤르메스의 발걸음과 전투 지속력을 높여주는 갈라진 하늘을 추천해요. 그웬의 마법 피해를 견디며 싸우는 데 도움이 돼요.', spell: '점멸과 점화를 추천해요. 그웬은 (P)\'가위 난도질\'로 챔피언에게 기본 공격할 때 체력을 회복하니 점화로 회복량을 줄여야 해요.' },
    '나르': { lv1: '나르가 (Q)\'부메랑 던지기\'로 둔화를 걸며 견제하니 거리를 조절하세요. 첫 웨이브를 맞으면서 (Q)\'야수의 송곳니\'를 활용해 체력을 회복하며 버티는 것이 좋아요. 나르의 (Q)\'부메랑 던지기\'가 돌아오는 타이밍에 맞춰 평타를 섞어주세요.', lv3: '나르가 (E)\'폴짝\'으로 거리를 벌리려 하면 (Q)\'야수의 송곳니\'로 끈질기게 따라붙으세요. 나르의 (Q)\'부메랑 던지기\'를 맞은 뒤에는 (E)\'원시의 포효\'를 사용해 피해를 줄이고 공포를 걸어 거리를 띄우세요. 나르의 분노가 차서 메가 나르로 변하기 전까지 짧은 교환을 반복하는 게 좋아요.', lv6: '나르가 메가 나르로 변신해 (R)\'나르!\'를 사용하면 벽에 부딪히지 않도록 주의하며 거리를 조절하세요. 체력이 낮은 나르를 발견하면 (R)\'무한의 구속\'으로 제압하며 강력하게 몰아붙이세요. 메가 나르의 (W)\'쿵쾅\' 기절을 맞으면 스킬을 쓸 수 없으니 변신 전후 거리를 보고 (E)\'원시의 포효\'를 미리 써 두세요.', item: '몰락한 왕의 검을 첫 코어로 올려 지속적인 싸움 능력을 높이세요. 신발은 나르의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 유체화를 추천해요. 유체화로 나르의 (E)\'폴짝\' 이후에도 거리를 좁혀 (Q)\'야수의 송곳니\'를 맞히기 쉬워져요.' },
    '나서스': { lv1: '나서스는 초반에 (Q)\'흡수의 일격\'으로 막타를 먹으며 성장하는 데 집중해요. 1~2레벨 구간에는 (Q)\'야수의 송곳니\'로 적극적으로 싸워 나서스의 체력을 깎고 성장을 방해하세요. (P)\'끝없는 허기\'의 회복을 활용해 교환을 이어나가며 라인을 주도하세요.', lv3: '나서스의 (W)\'쇠약\'에 걸리면 이동 속도와 공격 속도가 줄어들어 대응하기 어려워져요. 나서스가 (W)\'쇠약\'을 쓰려고 할 때 (E)\'원시의 포효\'를 사용하여 피해를 줄이고 공포를 걸어 거리를 벌리세요. (E)\'영혼의 불길\' 장판 위에서 싸우면 방어력이 낮아지니 피하는 것이 좋아요.', lv6: '나서스가 (R)\'사막의 분노\'를 사용하면 체력과 공격 범위가 늘어나니 무리하게 붙지 마세요. 나서스의 궁극기가 끝난 뒤 (R)\'무한의 구속\'으로 제압하여 킬을 노리는 것이 좋아요. 라인을 밀어 넣으며 정글러를 불러서 나서스가 막타를 챙기지 못하도록 압박하세요.', item: '나서스의 높은 체력을 깎기 위해 몰락한 왕의 검을 첫 코어로 가세요. 신발은 나서스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 나서스의 체력 회복 효과를 감소시켜 초반 킬각을 잡기 편해져요.' },
    '녹턴': { lv1: '1~2레벨에는 (Q)\'황혼의 인도자\' 견제를 조심하며 거리 조절을 하세요. 적이 궤적을 남겨 이동 속도가 빨라지기 전에 (Q)\'야수의 송곳니\'로 빠르게 진입해 짧은 딜교환을 하세요. 무리하게 쫓기보다 체력을 보존하며 다음 기회를 노리는 것이 좋아요.', lv3: '(E)\'원시의 포효\'로 피해를 줄이면서 진입하고 상대의 (W)\'어둠의 장막\'이 빠진 것을 확인한 뒤 공격하세요. (E)\'말할 수 없는 공포\'에 걸렸을 때는 빠르게 거리를 벌려 공포 효과를 피하는 것이 중요해요. (Q)\'야수의 송곳니\'를 길게 눌러 도망가는 녹턴을 따라가며 체력을 회복하세요.', lv6: '(R)\'피해망상\'으로 시야가 가려진 상태에서 날아오는 상대의 돌격에 대비해 (E)\'원시의 포효\'를 먼저 켜두세요. 적의 체력이 낮아졌을 때 (R)\'무한의 구속\'으로 제압하여 확실하게 처치하세요. 라인을 밀어넣고 정글러와 함께 상대의 시야 밖을 공략하는 것이 좋아요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화는 기본 공격 피해를 줄여주고 갈라진 하늘은 체력과 공격력을 제공하며 체력을 회복하게 도와줘요.', spell: '점멸과 점화를 추천해요. (E)\'말할 수 없는 공포\'의 범위를 빠르게 벗어나기 위해 점멸이 필요하고 점화로 (P)\'그림자 칼날\'의 회복을 억제하며 처치하기 좋아요.' },
    '다리우스': { lv1: '다리우스는 (P)\'과다출혈\' 중첩을 쌓아 강해지니 1~2레벨에 길게 붙어 싸우지 마세요. (Q)\'학살\'의 도끼날 끝에 맞지 않게 주의하고, (Q)\'야수의 송곳니\'로 짧게 체력을 회복하며 거리 조절을 하세요. 내 체력이 낮아져 (P)\'끝없는 허기\' 회복량이 늘어날 때만 짧게 딜교환을 시도하세요.', lv3: '(E)\'포획\'에 끌려가면 공중에 떠서 스킬을 쓸 수 없으니 끌려오기 전에 (E)\'원시의 포효\'를 미리 켜서 받는 피해를 줄이세요. 끌려온 뒤에는 (W)\'마비의 일격\' 둔화와 함께 중첩이 빠르게 쌓이니 포효가 끝날 때 나오는 공포로 다리우스를 떼어내세요. (E)\'포획\'이 빠진 것을 확인한 뒤 (Q)\'야수의 송곳니\'로 진입해 짧게 몰아치고 빠지세요.', lv6: '(R)\'녹서스의 단두대\'는 (P)\'과다출혈\' 중첩이 높을 때 치명적이니 중첩이 쌓이면 즉시 거리를 벌리세요. (R)\'무한의 구속\'으로 다리우스를 제압해 공격 흐름을 끊거나, (W)\'피의 사냥\'으로 속도를 높여 빠르게 진입해 킬각을 보세요. 라인을 당겨 정글러가 합류하기 쉬운 위치에서 싸우세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력과 공격력을 챙기고 라이트실드 타격으로 체력을 회복하며 버티세요. 신발은 다리우스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 다리우스의 (Q)\'학살\'을 통한 체력 회복을 억제하고 킬각을 잡을 때 유용해요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'를 사용하여 멀리서 견제하지만 1~2레벨에는 스킬이 부족해 공격이 약해요. 미니언 사이에서 거리 조절을 하며 라이즈의 (Q)\'과부하\'를 피하고 체력을 관리하세요. 라이즈가 미니언을 치려 할 때 (Q)\'야수의 송곳니\'로 접근해 맞대응하면 좋아요.', lv3: '라이즈가 (E)\'주문 전이\'로 표식을 남긴 뒤 (W)\'룬 감옥\'을 쓰면 둔화 대신 속박되니 주의하세요. (W)\'룬 감옥\'은 대상 지정이라 걸어서 피할 수 없으니 표식이 없을 때 (E)\'원시의 포효\'를 켜고 파고들어 피해를 줄이세요. (Q)\'야수의 송곳니\'로 라이즈를 물고 (E)\'원시의 포효\'의 공포를 활용해 딜교환을 이어나가세요.', lv6: '라이즈는 (R)\'공간 왜곡\'으로 빠져나갈 수 있으니 차원문을 여는 모습이 보이면 오래 끌지 말고 (R)\'무한의 구속\'으로 빠르게 제압해 몰아치세요. 라이즈의 체력이 낮아지면 (W)\'피의 사냥\' 효과로 더 빠르게 추격할 수 있어요. 다만 라이즈의 스킬 연계에 묶이지 않도록 (E)\'원시의 포효\'를 적절히 사용하여 대응하세요.', item: '몰락한 왕의 검을 첫 코어로 가서 체력 흡수와 전투력을 높이세요. 신발은 라이즈의 마법 피해와 군중 제어 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 라이즈를 확실하게 잡아내기 위해 점화로 마무리 피해를 입히고 킬각을 잡으세요.' },
    '럼블': { lv1: '럼블은 (Q)\'화염방사기\'로 정면의 넓은 범위를 공격하며 견제해요. (Q)\'야수의 송곳니\'로 짧게 진입해 피해를 입히고 빠르게 빠지며 체력을 관리하세요. 럼블이 과열 상태가 되어 스킬을 쓰지 못하는 틈을 타서 기본 공격으로 압박하는 것이 좋아요.', lv3: '(E)\'전기 작살\'에 맞으면 이동 속도가 느려지고 마법 저항력이 깎이니 주의해서 진입하세요. (Q)\'화염방사기\' 피해가 심할 때 (E)\'원시의 포효\'로 피해를 줄이고, 포효로 럼블을 공포에 빠뜨려 공격 기회를 잡으세요. (Q)\'야수의 송곳니\'를 길게 눌러 럼블이 이동해도 따라붙으며 압박하세요.', lv6: '(R)\'이퀄라이저 미사일\'이 깔린 구역은 지속 피해와 둔화가 심하므로 빠르게 범위를 벗어나세요. (W)\'피의 사냥\'으로 가속을 붙여 진입한 뒤, 럼블의 (W)\'고철 방패\'가 빠진 타이밍에 (R)\'무한의 구속\'으로 제압해 확실하게 킬각을 잡으세요. 라인을 밀었을 때는 럼블의 궁극기와 정글러의 호응이 강력하니 항상 주의하세요.', item: '맬모셔스의 아귀를 첫 코어로 선택해 마법 저항력을 높이고 생명선 보호막으로 생존력을 챙기세요. 신발은 마법 피해가 주력인 럼블을 상대로 마법 저항력을 주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 럼블은 (W)\'고철 방패\'로 피해를 흡수하니 점화의 지속 고정 피해로 마무리하세요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 피해를 주며 체력을 회복하므로 1~2레벨에 정면으로 맞붙는 것은 피하세요. 레넥톤의 분노가 높을 때는 거리를 유지하며 미니언을 챙기고, (Q)\'야수의 송곳니\'를 사용해 짧게 교환하며 체력을 회복하세요. 레넥톤이 (W)\'무자비한 포식자\'로 기절을 시도할 수 있으니 주의해야 해요.', lv3: '레넥톤이 (E)\'자르고 토막내기\'로 들어와 (W)\'무자비한 포식자\'로 기절을 시키려 할 때 (E)\'원시의 포효\'를 미리 사용하여 피해를 줄이세요. (E)\'자르고 토막내기\' 돌진이 빠졌을 때 (Q)\'야수의 송곳니\'를 길게 눌러 레넥톤을 물고 따라가며 딜교환을 하세요. 기절은 맞으면 스킬을 쓸 수 없으니 맞기 전에 스킬을 써 두고, 분노가 쌓이기 전에 (E)\'원시의 포효\'의 공포를 활용하세요.', lv6: '레넥톤이 (R)\'강신\'을 사용하여 체력을 늘리고 분노를 얻으면 무리하게 싸우지 말고 뒤로 물러나세요. 레넥톤이 (R)\'강신\' 상태에서 스킬을 쏟아붓고 난 뒤가 킬각이며, 이때 (R)\'무한의 구속\'으로 레넥톤을 제압하면 승기를 잡을 수 있어요. (R)\'무한의 구속\'으로 제압하는 동안은 레넥톤이 스킬을 쓸 수 없으니 확실하게 몰아붙이세요.', item: '몰락한 왕의 검을 첫 코어로 선택하여 전투 지속력을 높이세요. 신발은 레넥톤의 물리 피해를 줄여주는 판금 장화가 적합해요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'양떼 도륙\'의 회복 효과를 감소시켜 교환에서 이득을 보세요.' },
    '렝가': { lv1: '렝가가 수풀에서 (P)\'보이지 않는 포식자\'로 도약해 진입하는 것을 조심하며 거리를 유지하세요. (Q)\'야수의 송곳니\'를 사용하여 체력을 회복하며 버티고, 상대의 (Q)\'포악함\' 강화 평타 피해를 최소화하며 첫 웨이브를 받아내세요.', lv3: '렝가가 (E)\'올가미 투척\'을 던져 둔화를 걸고 진입할 때 (E)\'원시의 포효\'를 켜서 피해를 줄이고 공포로 적을 무력화하세요. (W)\'피의 사냥\'으로 이동 속도를 높여 추격하며, (Q)\'야수의 송곳니\'를 사용해 렝가의 체력을 깎으며 끈질기게 싸우세요.', lv6: '렝가가 (R)\'사냥의 전율\'로 위장해 도약할 때 (R)\'무한의 구속\'으로 제압하여 폭발적인 피해를 끊어내세요. 상대의 (W)\'전투의 포효\' 회복력을 고려해 빠르게 체력을 깎아야 하며, 라인을 당겨 정글러의 개입을 대비하세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화로 렝가의 기본 공격 피해를 줄이고, 갈라진 하늘의 체력과 공격력으로 유지력을 높이며 맞서기 좋아요.', spell: '점멸과 점화를 추천해요. 렝가의 (W)\'전투의 포효\' 회복 효과를 억제하고 확실하게 처치하기 위해 점화가 필요해요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'를 사용하여 빠르게 접근하며 (P)\'룬 검\'의 추가 피해를 입히기 때문에 초반 압박이 강해요. 1~2레벨에는 리븐의 돌진 거리를 신경 쓰며 (Q)\'야수의 송곳니\'로 적절히 맞받아쳐 체력을 회복하세요. 리븐이 기본 공격으로 (P)\'룬 검\' 충전을 다 쓴 뒤에 거리를 조절하며 대응하는 것이 좋아요.', lv3: '리븐의 (W)\'기 폭발\' 기절을 맞으면 대응하기 어려우니 리븐의 스킬이 빠지기 전에는 사정권 안에서 머물지 마세요. 리븐이 (E)\'용맹\'으로 보호막을 얻었을 때는 (E)\'원시의 포효\'를 사용하여 피해를 줄이며 타이밍을 기다려요. 리븐의 주요 스킬이 소모된 직후에 (Q)\'야수의 송곳니\'를 맞히며 적극적으로 딜교환을 하세요.', lv6: '리븐이 (R)\'추방자의 검\'을 켜면 공격력과 사거리가 늘어나니 궁극기가 지속되는 동안에는 (E)\'원시의 포효\'로 피해를 줄이며 거리를 조절하세요. 리븐이 궁극기 재사용까지 쓰고 (E)\'용맹\'이 빠진 뒤에 (R)\'무한의 구속\'으로 도약해 제압하세요. 라인을 밀어 넣은 뒤 리븐의 체력이 낮을 때 정글러의 개입을 유도하여 킬을 가져오세요.', item: '리븐의 물리 피해를 줄이기 위해 판금 장화를 선택해요. 첫 코어 아이템은 굶주린 히드라를 구매하여 생명력 흡수를 통해 유지력을 높이는 것이 좋아요.', spell: '점멸과 점화를 추천해요. 리븐의 (E)\'용맹\' 보호막이 빠진 뒤 점화로 마무리하여 킬을 가져오세요.' },
    '리산드라': { lv1: '리산드라의 (Q)\'얼음 파편\'은 처음 맞은 적 뒤로도 파편이 번지며 둔화를 걸기에 주의가 필요해요. 1~2레벨에는 무리하게 들어가기보다 미니언 체력을 관리하며 거리를 조절하세요. (Q)\'얼음 파편\'이 빠졌을 때 (Q)\'야수의 송곳니\'로 접근하여 체력을 회복하며 딜교환을 시도하세요.', lv3: '리산드라의 (W)\'서릿발\'은 속박이라 이동과 돌진을 막으니 맞은 상태에서는 (Q)\'야수의 송곳니\'로 붙을 수 없어요. (W)\'서릿발\'이나 (E)\'얼음갈퀴 길\'이 빠진 타이밍에 (E)\'원시의 포효\'를 켜고 들어가 피해를 줄이며 맞서세요. (W)\'서릿발\'을 맞은 직후에는 무리하게 싸우기보다 풀릴 때까지 거리를 벌리는 것이 좋아요.', lv6: '리산드라가 (R)\'얼음 무덤\'을 자신에게 사용하여 무적 상태가 되면 잠시 공격을 멈추고 기다려야 해요. 리산드라가 적에게 (R)\'얼음 무덤\'을 사용해 기절을 걸려고 할 때 (R)\'무한의 구속\'으로 먼저 제압하면 킬각을 잡기 편해요. (E)\'원시의 포효\'의 공포 효과를 활용해 리산드라의 스킬 연계를 끊는 것도 중요해요.', item: '헤르메스의 발걸음을 먼저 올려 마법 저항력과 강인함을 챙기세요. 첫 코어 아이템으로는 전투 지속력을 높여주는 몰락한 왕의 검을 추천해요.', spell: '점멸과 점화를 추천해요. 리산드라가 (R)\'얼음 무덤\'을 자신에게 써서 회복하는 양을 점화로 줄일 수 있어요. 다만 무적 상태에는 통하지 않으니 풀린 뒤 마무리에 쓰세요.' },
    '마스터이': { lv1: '1~2레벨에는 마스터 이의 (P)\'2연속 공격\'을 통한 평타 교환이 강해요. (Q)\'야수의 송곳니\'로 적에게 접근하며 체력을 회복하는 방식으로 대응하세요. 마스터 이가 (Q)\'일격 필살\'을 쓰기 전에 거리 조절을 하며 미니언과 함께 체력을 관리해요.', lv3: '마스터 이가 (W)\'명상\'을 사용하여 체력을 회복하고 피해를 줄이려 하면 (E)\'원시의 포효\'를 재사용하여 공포를 걸고 교환을 끊으세요. (Q)\'일격 필살\'을 사용해 대상으로 지정할 수 없는 동안에는 무리하게 스킬을 쓰지 말고 기다려요. 마스터 이의 (Q)\'일격 필살\'이 빠진 직후에 (Q)\'야수의 송곳니\'를 맞춰 체력을 회복하며 싸우세요.', lv6: '마스터 이가 (R)\'최후의 전사\'를 사용하면 둔화에 면역이 되므로 (E)\'원시의 포효\'로 공격 흐름을 끊어야 해요. (R)\'무한의 구속\'으로 마스터 이를 제압하면 둔화 면역과 상관없이 공격을 멈추게 할 수 있어요. 마스터 이가 킬을 먹고 스킬 쿨타임을 줄이지 못하도록 라인을 밀어 넣으며 정글러의 위치를 확인하세요.', item: '첫 코어로 갈라진 하늘을 가서 전투 지속력을 높이세요. 신발은 마스터 이의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 마스터 이가 (W)\'명상\'을 통해 체력을 회복하는 것을 억제해야 해요.' },
    '마오카이': { lv1: '마오카이가 (Q)\'덤불 주먹\'으로 밀어내며 둔화를 걸고 (P)\'마법 흡수\'로 체력을 회복하니 거리를 잘 조절하세요. (Q)\'야수의 송곳니\'를 사용하여 적을 물고 체력을 회복하며 맞딜을 하면 초반 싸움에서 맞대응하기 좋아요. 1~2레벨에는 마오카이가 다가올 때 무작정 싸우기보다 체력을 보존하며 웨이브를 받아내세요.', lv3: '마오카이가 (W)\'뒤틀린 전진\'으로 돌진해 속박을 걸면 이동이 막히니 주의하세요. (W)\'뒤틀린 전진\'이 빠진 것을 확인한 뒤에 (E)\'원시의 포효\'를 사용하여 피해를 줄이고 공포를 맞히며 싸우세요. (E)\'묘목 던지기\'에 맞으면 (P)\'마법 흡수\'의 재사용 대기시간이 줄어드니 묘목이 설치된 수풀 근처는 피하세요.', lv6: '마오카이의 (R)\'대자연의 마수\' 벽이 다가올 때는 벽이 오는 길목에서 벗어나 옆으로 이동하세요. 마오카이가 스킬을 사용해 위치가 노출되었을 때 (R)\'무한의 구속\'으로 제압하면 킬을 노리기 좋아요. 벽이 다가오는 도중에 싸우면 정글러의 개입에 대처하기 어려우니 라인 관리에 신경 쓰세요.', item: '마법 저항력을 높여주는 헤르메스의 발걸음을 신발로 선택하세요. 첫 코어 아이템은 생명력 흡수와 공격 속도를 보태주는 몰락한 왕의 검을 추천해요.', spell: '점멸과 점화를 추천해요. 마오카이가 (P)\'마법 흡수\'로 체력을 회복하는 것을 억제하며 전투를 마무리하기 좋아요.' },
    '말자하': { lv1: '말자하의 (P)\'공허 태세\'가 켜져 있으면 받는 피해가 크게 줄고 군중 제어에 면역이 되니 먼저 한 번 피해를 입혀 풀어 주세요. (Q)\'공허의 부름\'의 침묵에 걸리면 스킬을 못 쓰니 투사체가 오는 방향에서 빠르게 비켜나세요. 1~2레벨에는 무리하게 들어가기보다 (P)\'끝없는 허기\'의 회복력을 이용해 견제를 버티며 기회를 보세요.', lv3: '(E)\'재앙의 환상\'과 (W)\'공허의 무리\'가 동시에 들어오면 피해가 심하니 (E)\'원시의 포효\'로 피해를 줄이며 진입하세요. (Q)\'야수의 송곳니\'로 빠르게 접근해 (P)\'공허 태세\'를 지우고 평타 교환을 유도하세요. 상대가 (Q)\'공허의 부름\'을 사용해 침묵을 걸기 전에 스킬을 먼저 빠르게 사용하고 붙으세요.', lv6: '(R)\'황천의 손아귀\'는 제압이라 정화로 풀 수 없으며 제압 중에는 모든 행동이 막히니 각별히 조심하세요. (W)\'피의 사냥\'으로 이동 속도를 높인 뒤 (R)\'무한의 구속\'으로 덮쳐 상대를 먼저 제압하고 공격하세요. 라인을 내 포탑 쪽으로 당겨 두면 말자하가 앞으로 나와야 해서 덮치기 더 편해요.', item: '맬모셔스의 아귀를 추천해요. 마법 저항력을 챙기고 체력이 낮을 때 보호막을 얻어 말자하의 마법 피해를 버틸 수 있어요. 신발은 마법 저항력을 높이고 (Q)\'공허의 부름\' 침묵 지속 시간을 줄여 주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 제압은 정화로 풀 수 없으니 점멸로 거리를 조절하세요. 점화는 말자하를 마무리하는 지속 고정 피해로 써요.' },
    '말파이트': { lv1: '말파이트는 (P)\'화강암 방패\'로 피해를 흡수하며 (Q)\'지진의 파편\'으로 거리를 벌리고 이동 속도를 훔쳐요. (Q)\'야수의 송곳니\'로 도약해 체력을 회복하며 압박하되, 말파이트의 방패가 있을 때는 평타 교환을 피하며 웨이브를 받아내세요. 방패가 사라진 시점에 (Q)\'야수의 송곳니\'를 사용하여 적극적으로 맞딜을 하세요.', lv3: '말파이트가 (E)\'지면 강타\'를 사용하여 공격 속도를 낮추려 하면 (E)\'원시의 포효\'를 미리 켜서 피해를 줄이세요. 말파이트의 (Q)\'지진의 파편\'은 미니언 뒤로 숨어도 맞으니 체력 관리에 유의하며 (Q)\'야수의 송곳니\'로 짧게 치고 빠지는 것이 좋아요. 말파이트의 (W)\'천둥소리\'가 켜진 상태에서는 평타 교환을 피하고 (E)\'원시의 포효\'로 공포를 걸어 거리를 벌리세요.', lv6: '말파이트의 (R)\'멈출 수 없는 힘\'은 저지 불가 상태로 돌진해 공중으로 띄우니, 정글러가 근처에 있을 때 맞지 않도록 주의하세요. 말파이트가 궁극기를 사용한 직후에는 (R)\'무한의 구속\'으로 상대를 제압하며 체력을 회복하고 킬각을 보세요. 말파이트의 궁극기가 빠진 후에는 (Q)\'야수의 송곳니\'와 (E)\'원시의 포효\'를 활용해 라인을 강하게 밀어붙이세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 전투 중 체력을 회복하며 말파이트와 지속적인 싸움을 이어가세요. 신발은 말파이트의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (R)\'무한의 구속\'으로 상대를 제압하는 동안 점화로 피해를 높여 킬을 가져오기 좋아요.' },
    '모데카이저': { lv1: '모데카이저의 (Q)\'말살\'은 단일 대상에게 맞으면 피해가 커지니 미니언 사이에 서서 혼자 맞지 않도록 거리를 조절하세요. 1~2레벨에는 (Q)\'야수의 송곳니\'로 적의 체력을 깎으며 체력을 회복하고, (P)\'암흑 탄생\' 오라가 켜지기 전에 거리를 조절하세요.', lv3: '모데카이저가 (E)\'죽음의 손아귀\'로 끌어당기려 할 때 (E)\'원시의 포효\'를 사용하여 피해를 줄이고 공포를 입히세요. (W)\'불멸\' 보호막이 활성화된 상태에서는 무리하게 붙지 말고, 보호막이 사라진 것을 확인한 뒤 (Q)\'야수의 송곳니\'로 진입하세요.', lv6: '모데카이저의 (R)\'죽음의 세계\'에 끌려가면 능력치를 뺏기며 그 안에서는 빠져나올 수 없으니 주의하세요. 전투 시에는 (R)\'무한의 구속\'으로 모데카이저를 제압하여 대응하고, (P)\'끝없는 허기\' 패시브의 회복력을 활용해 싸움을 이어가세요.', item: '첫 코어로 갈라진 하늘을 선택해 체력을 확보하고 전투에 도움을 받으세요. 신발은 모데카이저의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (W)\'불멸\'로 체력을 회복하려는 모데카이저의 회복량을 줄여서 킬각을 잡기 좋아요.' },
    '문도박사': { lv1: '문도 박사는 (Q)\'오염된 뼈톱\'으로 현재 체력에 비례한 피해를 주며 둔화를 걸어요. 이 투사체는 처음 맞는 적에게 적중하니 미니언 뒤에 서서 막아내고, (Q)\'야수의 송곳니\'로 빠르게 붙어 체력을 회복하며 압박하세요. 초반에는 짧은 교환을 반복하며 상대의 체력을 깎아 (W)\'피의 사냥\' 효과를 받는 것이 중요해요.', lv3: '문도 박사가 (W)\'심장 전기 충격\'을 켜면 받는 피해를 저장해 회복하니, 효과가 지속되는 동안에는 무리하게 붙어 싸우지 마세요. (E)\'원시의 포효\'를 사용해 피해를 줄이며 버티다가, 스킬이 끝나는 시점에 맞춰 (Q)\'야수의 송곳니\'로 들어가 딜교환을 하세요. 상대의 (E)\'둔기에 의한 외상\'은 잃은 체력에 비례해 강해지니 문도의 체력이 낮을 때 너무 오래 머물지 마세요.', lv6: '문도 박사가 (R)\'최대 투여량\'을 쓰면 체력 회복과 이동 속도가 크게 늘어나니, 회복량이 높은 구간에는 무리하게 추격하지 마세요. (R)\'최대 투여량\'이 끝난 뒤 정글러와 함께 (R)\'무한의 구속\'으로 제압하면 킬각을 잡기 좋아요. (Q)\'야수의 송곳니\'와 함께 사용해 빠르게 체력을 깎아 상대의 재생력을 앞지르는 것이 핵심이에요.', item: '몰락한 왕의 검을 첫 코어로 가서 체력이 높은 문도 박사를 빠르게 깎으세요. 신발은 마법 저항력을 높여 (Q)\'오염된 뼈톱\'과 (W)\'심장 전기 충격\'의 피해를 줄이는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 문도 박사는 체력 재생과 스킬 회복이 매우 강력해서 점화의 치유 감소 효과가 있어야 처치할 수 있어요.' },
    '바루스': { lv1: '(Q)\'꿰뚫는 화살\'은 조준 시간이 길수록 사거리와 피해가 늘어나니 조준하는 모습이 보이면 옆으로 움직여 피하세요. 무작정 다가가면 견제를 많이 맞으니 화살이 빠진 틈에 (Q)\'야수의 송곳니\'로 빠르게 진입해 기본 공격을 가하세요.', lv3: '(E)\'퍼붓는 화살\'은 이동 속도를 늦추고 회복량을 줄이니 그 장판 위에서 싸우는 것을 피하세요. 진입할 때 (E)\'원시의 포효\'를 켜서 피해를 줄이고, 바루스가 스킬을 쓰려 할 때 포효의 공포로 흐름을 끊으세요. (Q)\'야수의 송곳니\'로 계속 붙어 있으며 (W)\'피의 사냥\'의 공격 속도 증가 효과를 활용해 압박하세요.', lv6: '(R)\'부패의 사슬\'에 속박되면 진입이 끊기니 바루스의 궁극기가 빠진 것을 확인하고 진입하세요. 바루스의 체력이 낮아지면 (R)\'무한의 구속\'으로 확실하게 제압하며 킬각을 잡으세요. (W)\'피의 사냥\'으로 이동 속도를 높여 (R)\'무한의 구속\'의 도약 거리를 최대한 활용해 기습하는 것이 좋아요.', item: '몰락한 왕의 검을 첫 코어로 가서 공격 속도와 생명력 흡수로 유지력을 높이고 바루스에게 더 잘 붙으세요. 신발은 바루스의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도 증가 효과가 원거리인 바루스에게 접근하는 데 큰 도움이 돼요.' },
    '베인': { lv1: '베인은 (Q)\'구르기\'로 거리를 벌리며 (W)\'은화살\'의 세 번째 공격을 노리니 무작정 다가가지 마세요. 1~2레벨에는 (E)\'원시의 포효\'를 사용해 피해를 줄이며 버티고, 베인이 (Q)\'구르기\'를 사용해 거리를 벌릴 때를 기다려야 해요. (Q)\'야수의 송곳니\'로 진입할 때는 베인의 (E)\'선고\'를 맞지 않도록 주의하세요.', lv3: '베인의 (E)\'선고\'를 맞으면 뒤로 밀려나니 지형 근처에서는 조심하며 (E)\'원시의 포효\'를 먼저 사용하세요. (Q)\'야수의 송곳니\'로 베인을 물었을 때 (Q)\'구르기\'로 빠지려 하면 (E)\'원시의 포효\'를 재사용해 공포로 스킬 연계를 끊으세요. 베인이 (W)\'은화살\'의 세 번째 타격을 채우기 전에 빠르게 딜교환을 시도하세요.', lv6: '(R)\'무한의 구속\'으로 베인을 제압하면 강력한 피해를 입히며 체력을 회복할 수 있어요. 베인이 (R)\'결전의 시간\'을 쓰면 (Q)\'구르기\' 때 투명 상태가 되니 궁극기를 켜기 전에 제압을 맞히는 것이 좋아요. 라인을 당겨서 관리하며 정글러를 불러 베인이 (E)\'선고\'를 쓰기 전에 먼저 덮치세요.', item: '몰락한 왕의 검을 첫 코어로 가서 베인과의 맞딜 능력을 높이세요. 신발은 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화로 베인의 (Q)\'구르기\'를 따라잡아 빠르게 접근한 뒤 (R)\'무한의 구속\'을 맞히기 쉬워져요.' },
    '볼리베어': { lv1: '볼리베어는 (Q)\'번개 강타\'로 빠르게 달려와 기절을 걸려고 해요. (Q)\'야수의 송곳니\'로 무리하게 진입하기보다 상대의 진입을 기다리며 (P)\'끝없는 허기\' 피해로 짧게 교환하세요. 기절을 맞은 상태에서 (P)\'무자비한 폭풍\'의 공격 속도 증가 효과에 노출되면 피해가 크니 주의하세요.', lv3: '볼리베어가 (E)\'천공 분열\'로 보호막을 얻으려 할 때 (E)\'원시의 포효\'를 켜서 피해를 줄이고 공포로 밀어내세요. (W)\'광란의 상처\' 표식이 남은 상태에서 교환을 길게 끌면 볼리베어가 체력을 회복하니 적절히 거리를 벌리세요. (Q)\'번개 강타\'가 빠진 것을 확인한 뒤 (Q)\'야수의 송곳니\'로 붙어 공격하세요.', lv6: '볼리베어가 (R)\'폭풍을 부르는 자\'로 포탑을 비활성화하며 다이브를 시도할 수 있으니 체력이 낮을 때 포탑 뒤라고 안심하지 마세요. 상대가 도약해 들어온 직후 (R)\'무한의 구속\'으로 제압해 추가 체력 효율을 누르고 빠르게 처치하세요. (W)\'피의 사냥\'의 이동 속도를 활용해 상대의 진입 경로를 예측하며 대응하세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력과 공격력을 높이고 전투 중 체력을 회복하세요. 신발은 강인함으로 (Q)\'번개 강타\'의 기절 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 볼리베어는 (W)\'광란의 상처\'로 체력을 회복하므로 점화로 회복 효과를 감소시켜야 해요.' },
    '블라디미르': { lv1: '블라디미르는 (Q)\'수혈\'로 체력을 회복하며 견제해요. (Q)\'수혈\'은 대상을 지정하는 스킬이라 미니언 뒤에 숨어도 피할 수 없으니 주의하세요. (Q)\'야수의 송곳니\'로 빠르게 접근해 짧게 딜교환을 하고 빠지는 방식으로 체력 압박을 주세요.', lv3: '(E)\'선혈의 파도\'는 적 유닛이 가로막을 수 있으니 미니언 뒤에 서서 피해를 줄이세요. 블라디미르가 (W)\'피의 웅덩이\'를 쓰면 대상 지정이 안 되니, 웅덩이가 끝나는 타이밍에 맞춰 (E)\'원시의 포효\'로 공포에 빠뜨리세요. (W)\'피의 웅덩이\' 동안에는 (Q)\'야수의 송곳니\'를 아껴 두었다가 웅덩이가 끝난 뒤에 쓰세요.', lv6: '(R)\'혈사병\'에 감염되면 받는 피해가 늘어나니 감염된 동안은 무리하게 진입하지 마세요. (W)\'피의 웅덩이\'가 빠진 것을 확인한 뒤 (R)\'무한의 구속\'으로 제압하여 확실하게 킬각을 잡으세요. 라인을 밀어 넣고 정글러를 불러 (Q)\'수혈\' 회복량을 압도하는 다수 공격으로 빠르게 처치하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 생명력 흡수와 공격 속도로 압박하세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (Q)\'수혈\'로 회복하는 양이 많으므로 점화의 치유 감소 효과로 이를 억제해야 해요.' },
    '뽀삐': { lv1: '뽀삐가 (Q)\'망치 강타\'로 만든 둔화 지대를 피해 움직이고 (P)\'강철의 외교관\' 보호막이 사라진 뒤에 딜교환을 하세요. 뽀삐가 방패를 줍기 위해 이동할 때 평타로 압박하며 체력을 깎으세요. (Q)\'야수의 송곳니\'를 짧게 써서 피해를 입히고 빠르게 빠지며 체력을 관리하세요.', lv3: '(W)\'굳건한 태세\'가 켜져 있으면 (Q)\'야수의 송곳니\' 돌진이 막히고 둔화되니 이 스킬이 빠진 것을 확인하고 진입하세요. 뽀삐가 (E)\'용감한 돌진\'으로 벽에 밀어 기절시키려 하면 라인 중앙으로 움직여 피해를 줄이세요. (E)\'원시의 포효\'의 피해 감소 효과를 이용해 뽀삐의 공격을 버틴 뒤 포효로 상대를 공포에 빠뜨리세요.', lv6: '(R)\'무한의 구속\'은 돌진기라 뽀삐의 (W)\'굳건한 태세\'에 막히면 역습을 당하니 상대 스킬이 빠진 뒤에 사용하세요. (R)\'수호자의 심판\'에 맞으면 멀리 날아가 딜교환이 끊기니 뽀삐가 망치를 충전할 때 옆으로 피하세요. 적의 체력이 낮아 (W)\'피의 사냥\'이 발동하면 빠른 속도로 접근해 (R)\'무한의 구속\'으로 제압하며 킬각을 잡으세요.', item: '판금 장화를 신어 뽀삐의 기본 공격 피해를 줄이세요. 첫 코어 아이템으로는 칠흑의 양날 도끼를 가서 단단한 뽀삐의 방어력을 깎으세요.', spell: '점멸과 점화를 추천해요. 점화의 추가 피해로 뽀삐의 높은 체력을 깎아 킬각을 잡기 좋아요.' },
    '사이온': { lv1: '사이온이 (Q)\'대량 학살 강타\'를 충전해 맞히면 기절하니 충전 동작을 보고 옆으로 비켜서세요. (E)\'학살자의 포효\'는 미니언에 맞으면 미니언이 밀려나 뒤의 적까지 맞히니 미니언 뒤로 피하려 하지 말고 옆으로 비켜서세요. 사이온이 스킬을 쓰기 전 (Q)\'야수의 송곳니\'로 빠르게 진입해 체력을 회복하며 딜교환을 하세요.', lv3: '사이온의 (W)\'영혼의 용광로\' 보호막이 켜져 있을 때는 피해가 흡수되니 보호막이 사라진 뒤에 (Q)\'야수의 송곳니\'로 물고 공격하세요. 사이온이 (E)\'학살자의 포효\'로 방어력을 낮추려 하면 (E)\'원시의 포효\'를 사용해 피해를 줄이고 공포를 시키세요. 사이온이 (Q)\'대량 학살 강타\'를 쓸 때 옆으로 피한 뒤 (W)\'피의 사냥\'의 이동 속도 증가를 활용해 거리를 좁히세요.', lv6: '사이온이 (R)\'멈출 수 없는 맹공\'으로 돌진하면 경로에서 벗어나 기절을 피하고 (R)\'무한의 구속\'으로 사이온을 제압하세요. 제압 중에는 사이온이 도망치기 어려우니 확실하게 딜을 넣어 마무리하세요. 사이온은 (P)\'영광스러운 죽음\'으로 잠시 되살아나니 처치 후에도 바로 멀어지거나 다음 행동을 준비하세요.', item: '사이온의 높은 체력을 깎기 위해 몰락한 왕의 검을 첫 코어로 선택하세요. 신발은 사이온의 군중 제어 지속 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 사이온은 라인을 밀어 두는 경우가 많으니 순간이동으로 합류하거나 라인 복귀를 하는 게 좋아요.' },
    '사일러스': { lv1: '사일러스가 (Q)\'사슬 후려치기\'로 견제하며 (P)\'페트리사이트 폭발\'을 충전할 때 평타를 조심하세요. (Q)\'야수의 송곳니\'로 바로 싸우기보다 사일러스의 사슬이 빠진 후에 (P)\'끝없는 허기\'의 체력 회복을 활용해 맞받아치세요. 1~2레벨 구간에서는 무리한 진입을 피하고 미니언을 챙기며 거리를 조절하세요.', lv3: '사일러스가 (W)\'국왕시해자\'를 사용하여 체력을 회복하는 것을 먼저 유도한 뒤 (E)\'원시의 포효\'로 피해를 줄이고 공포를 거세요. (E)\'도주 / 억압\'의 두 번째 사용에 맞으면 공중으로 뜨니 사일러스의 돌진에 맞춰 (Q)\'야수의 송곳니\'를 쓰거나 (E)\'원시의 포효\'를 재사용하세요. (Q)\'사슬 후려치기\'의 교차 지점을 피해 옆으로 움직이며 평타로 (P)\'끝없는 허기\' 회복을 챙기세요.', lv6: '사일러스가 (R)\'강탈\'로 내 (R)\'무한의 구속\'을 훔쳐 가면 제압 능력을 사용할 수 있으니 주의하세요. 사일러스가 (W)\'국왕시해자\'를 사용해 체력을 회복하는 타이밍에 (R)\'무한의 구속\'으로 제압하여 딜교를 이어가세요. 사일러스가 훔친 궁극기를 확인하고 정글러의 개입에 대비해 라인 관리와 위치 선정을 하세요.', item: '몰락한 왕의 검을 첫 코어로 가서 맞대결 능력을 높이세요. 신발은 마법 저항력을 제공하는 헤르메스의 발걸음을 선택하세요.', spell: '점멸과 점화를 추천해요. 사일러스가 (W)\'국왕시해자\'로 체력을 회복하는 것을 점화로 억제하세요.' },
    '세주아니': { lv1: '1~2레벨에는 (Q)\'혹한의 맹습\'을 통한 돌진을 주의하며 거리를 유지해야 해요. (Q)\'야수의 송곳니\'를 활용해 체력을 회복하며 상대의 접근을 방어하세요. 상대의 (W)\'혹한의 서릿발\' 중첩이 쌓이지 않게 조심해야 해요.', lv3: '3레벨에는 상대의 (W)\'혹한의 서릿발\'을 조심하며 (E)\'원시의 포효\'를 준비하세요. (Q)\'혹한의 맹습\'이 빠진 것을 확인한 뒤 (Q)\'야수의 송곳니\'를 사용하여 딜교환을 시도해요. (E)\'원시의 포효\'로 들어오는 피해를 줄이며 버텨야 해요.', lv6: '(R)\'무한의 구속\'으로 상대를 제압하면 피해를 주며 체력을 회복해 킬을 노릴 수 있어요. (R)\'빙하 감옥\'에 맞으면 기절해 스킬을 쓸 수 없으니 올가미가 날아오는 방향을 보고 옆으로 피하세요. (Q)\'혹한의 맹습\'으로 들어올 때 (E)\'원시의 포효\'를 미리 켜서 피해를 줄이며 교전하세요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 추천해요. 상대의 기절 지속시간을 줄이기 위해 헤르메스의 발걸음을 가고 생명력 흡수를 위해 몰락한 왕의 검을 선택하세요.', spell: '점멸과 점화를 추천해요. 점멸로 거리를 조절하고 점화로 마무리 피해를 입히며 킬을 노려요.' },
    '세트': { lv1: '세트는 (Q)\'주먹다짐\'을 켜고 달려와서 하는 기본 공격이 매우 강력해요. (Q)\'야수의 송곳니\'를 활용해 짧게 끊어 치며 체력을 회복하고 거리를 조절하세요. 세트가 (Q)\'주먹다짐\'의 강화 평타를 쓰려고 다가올 때는 (E)\'원시의 포효\'로 피해를 줄이며 버텨야 해요.', lv3: '세트의 (W)\'강펀치\'는 투지를 모아 큰 보호막과 고정 피해를 주니, 세트가 피해를 입어 투지가 쌓였을 때 (E)\'원시의 포효\'를 미리 사용하여 피해를 줄이세요. (E)\'안면 강타\'를 맞으면 기절하거나 둔화되니 미니언과 너무 가깝게 붙어 있지 마세요. (Q)\'야수의 송곳니\'를 길게 사용하여 세트의 움직임을 따라가며 체력을 회복하며 싸우세요.', lv6: '세트가 (R)\'대미 장식\'으로 붙잡으면 제압 상태라 스킬을 쓸 수 없으니 붙잡히기 전에 거리를 두세요. 세트의 (W)\'강펀치\' 보호막이 사라지는 타이밍에 (R)\'무한의 구속\'으로 제압하며 몰아붙이면 킬을 노리기 좋아요. (W)\'피의 사냥\'의 이동 속도로 빠르게 접근해 기회를 만드세요.', item: '몰락한 왕의 검을 가서 공격 속도와 생명력 흡수를 챙기세요. 신발은 세트의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 세트는 (P)\'투기장의 투지\'로 잃은 체력에 비례해 체력을 회복하니 점화로 회복량을 줄여야 해요.' },
    '쉔': { lv1: '쉔은 (Q)\'황혼 강습\'으로 최대 체력 비례 피해를 주고 스킬을 쓰면 (P)\'기 보호막\'을 얻어서 정면 교환이 힘들어요. (P)\'기 보호막\'이 켜져 있을 때는 평타 교환을 피하고, 보호막이 사라진 뒤에 짧게 평타를 치고 빠지세요. 쉔이 기의 검을 불러들일 때 둔화에 걸리지 않도록 거리 조절을 하며 (P)\'끝없는 허기\'의 회복력을 활용하세요.', lv3: '(W)\'의지의 결계\'가 켜진 동안은 기본 공격이 차단되니, 이때는 평타 대신 (E)\'원시의 포효\'를 켜서 피해를 줄이며 버티세요. (E)\'그림자 돌진\'에 도발되면 스킬을 쓸 수 없으니, 도발이 끝난 직후 (Q)\'야수의 송곳니\'로 도약해 체력을 회복하며 딜교환하세요. 쉔의 (Q)\'황혼 강습\' 강화 평타가 빠진 시점을 노려 (W)\'피의 사냥\'의 공격 속도 증가를 활용해 빠르게 공격하세요.', lv6: '(R)\'단결된 의지\'로 쉔이 아군에게 합류해 자리를 비우면 빠르게 라인을 밀어 포탑을 압박하세요. 쉔이 다시 돌아오면 (R)\'무한의 구속\'으로 제압해 (P)\'기 보호막\'이 다시 생성되기 전에 폭발적인 피해를 넣으세요. (E)\'원시의 포효\'의 공포 효과로 쉔의 (E)\'그림자 돌진\' 진입 각도를 제한하며 거리 조절을 하는 것이 중요해요.', item: '몰락한 왕의 검을 첫 코어로 가서 쉔의 높은 체력을 깎고 생명력 흡수로 버티세요. 신발은 (E)\'그림자 돌진\'의 도발 지속 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 쉔이 (R)\'단결된 의지\'로 합류할 때 함께 이동해서 팀 교전에 참여하세요.' },
    '쉬바나': { lv1: '(Q)\'잉걸불 일격\'의 강화 평타 타이밍을 피하며 짧게 딜교환하세요. (Q)\'야수의 송곳니\'를 사용해 빠르게 붙었다가 떨어지는 방식으로 체력을 깎으세요. 상대의 (E)\'용암 분출\' 둔화에 걸리지 않도록 주의하며 거리 조절을 해요.', lv3: '(W)\'지옥불 방패\'의 보호막이 사라진 뒤에 (Q)\'야수의 송곳니\'로 진입하세요. (E)\'원시의 포효\'로 상대의 폭발 피해를 감소시키고 공포로 접근을 차단해요. (Q)\'잉걸불 일격\'의 피해를 최소화하면서 기본 공격으로 (P)\'끝없는 허기\'의 회복을 노리세요.', lv6: '상대가 (R)\'용의 강림\'으로 진입해 착지한 뒤 (R)\'무한의 구속\'으로 제압하세요. 용 형상일 때는 (E)\'용암 분출\'의 범위와 피해가 강력하니 정면 승부를 피하며 싸워요. 라인을 당겨서 정글러와 함께 (R)\'무한의 구속\' 연계 킬각을 잡으세요.', item: '헤르메스의 발걸음과 정령의 형상을 추천해요. 마법 저항력을 높여 (E)\'용암 분출\'과 (W)\'지옥불 방패\' 폭발 같은 마법 피해를 줄이고, 정령의 형상은 받는 회복 효과를 늘려 (P)\'끝없는 허기\' 회복을 키워요.', spell: '점멸과 점화를 추천해요. (W)\'지옥불 방패\'의 체력 회복을 억제하고 킬각을 잡기 좋기 때문이에요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 견제하며 (P)\'굶주린 새떼\'로 체력을 회복해요. (Q)\'죽음의 손길\' 번개가 여러 갈래로 퍼지니 옆으로 피하며 (Q)\'야수의 송곳니\'로 순식간에 거리를 좁혀 공격하세요. (P)\'끝없는 허기\'를 통해 체력을 유지하며 스웨인이 영혼 조각을 모으기 전에 압박을 넣는 것이 좋아요.', lv3: '(E)\'속박명령\' 파동이 돌아올 때 속박되므로 파동의 궤적을 보고 옆으로 움직여 피하세요. 속박에 걸려도 (E)\'원시의 포효\'는 사용할 수 있으니 피해 감소 효과를 켜서 스웨인의 공격을 받아내세요. (W)\'피의 사냥\'으로 이동 속도를 높여 진입한 뒤 (E)\'원시의 포효\' 공포로 상대의 공격 흐름을 끊으세요.', lv6: '스웨인이 (R)\'악의 승천\'을 켜면 주변 적의 체력을 흡수하니 무작정 붙어있지 말고 적절히 거리를 두세요. (R)\'무한의 구속\'으로 스웨인을 제압하면 큰 피해를 입히며 체력을 회복할 수 있어요. (W)\'제국의 눈\'에 맞으면 위치가 드러나 정글러의 개입이 쉬워지니 주의하며 라인을 관리하세요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 추천해요. 헤르메스의 발걸음은 (E)\'속박명령\'의 속박 시간을 줄여주고 맬모셔스의 아귀는 마법 저항력과 생명선 보호막으로 생존력을 높여줘요.', spell: '점멸과 점화를 추천해요. 스웨인은 (R)\'악의 승천\'과 (P)\'굶주린 새떼\'로 계속 체력을 회복하므로 점화의 치유 감소 효과가 꼭 필요해요.' },
    '스카너': { lv1: '1~2레벨에는 스카너가 (Q)\'부서진 대지/지반 돌출\'로 바위를 강화해 던지며 견제하니 던지는 방향을 보고 옆으로 피하세요. (Q)\'야수의 송곳니\'를 사용해 짧게 딜교환을 하고 빠르게 빠져나오는 것이 좋아요. 상대의 공격 속도 강화 타이밍을 피해 거리를 조절하세요.', lv3: '(W)\'대지의 수호자\'로 보호막과 둔화가 적용되었을 때는 (E)\'원시의 포효\'를 켜서 피해를 줄이며 버티세요. 스카너가 (E)\'이쉬탈의 격돌\'로 밀어붙이려 할 때 포효를 재사용해 공포로 밀어내면 교전을 편하게 이끌 수 있어요. 그 뒤 (Q)\'야수의 송곳니\'로 붙어 지속 피해를 입히세요.', lv6: '스카너의 (R)\'꿰뚫기\'에 맞으면 제압되어 끌려가니 스카너가 쓰기 전에 (R)\'무한의 구속\'으로 먼저 제압해 흐름을 끊으세요. (W)\'피의 사냥\'으로 이동 속도를 높여 상대의 스킬 범위를 빠르게 벗어나거나 역습하는 것이 중요해요. 라인을 당겨서 정글러가 개입하기 좋은 환경을 만드세요.', item: '판금 장화와 몰락한 왕의 검을 추천해요. 판금 장화로 기본 공격 피해를 줄이고 몰락한 왕의 검으로 체력이 높은 상대를 효율적으로 공격하기 위해서예요.', spell: '점멸과 점화를 추천해요. 적의 체력을 빠르게 깎아 (W)\'피의 사냥\'의 공격 속도 증가 효과를 얻고 킬각을 잡기 위해서예요.' },
    '신지드': { lv1: '신지드는 (Q)\'맹독의 자취\'로 독구름을 남기며 라인을 빠르게 밀려고 해요. 독구름 위에서는 싸우지 말고 미니언 사이에서 거리 조절을 하며 (Q)\'야수의 송곳니\'로 짧게 딜교하세요. 신지드가 다가올 때 (E)\'원시의 포효\'를 아껴두었다가 거리를 벌리는 용도로 사용하세요.', lv3: '신지드의 (W)\'초강력 접착제\'를 맞으면 (Q)\'야수의 송곳니\'를 사용할 수 없으니 주의하세요. 신지드가 (E)\'던져넘기기\'를 쓰려 할 때 (E)\'원시의 포효\'를 재사용해 공포를 맞히면 딜교에서 앞서요. (W)\'초강력 접착제\'가 빠진 것을 확인한 뒤 (Q)\'야수의 송곳니\'를 길게 사용하여 체력을 회복하며 싸우세요.', lv6: '신지드가 (R)\'광기의 물약\'을 사용하면 (Q)\'맹독의 자취\'의 효과로 체력 회복이 줄어드니 정면 싸움은 피하세요. (R)\'무한의 구속\'으로 신지드를 제압하고 (Q)\'야수의 송곳니\'를 연계하면 충분히 킬을 노릴 수 있어요. 신지드가 라인을 밀 때 (R)\'무한의 구속\'으로 추격하거나 정글러와 함께 압박하세요.', item: '첫 코어로 몰락한 왕의 검을 선택해 지속 싸움 능력을 높이세요. 신지드의 마법 피해를 견디고 군중 제어 지속시간을 줄이기 위해 헤르메스의 발걸음을 신으세요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 신지드의 (Q)\'맹독의 자취\'를 빠르게 지나치거나 (R)\'무한의 구속\'을 맞히기 쉬워요.' },
    '아이번': { lv1: '아이번은 (Q)\'덩굴뿌리\'로 멀리서 속박을 걸어 견제하니 맞으면 이동과 돌진이 막혀요. 던지는 방향을 보고 옆으로 피한 뒤 (Q)\'덩굴뿌리\'가 빠진 틈에 (Q)\'야수의 송곳니\'로 진입해 피해를 입히세요. 미니언 체력을 관리하며 체력을 적절히 유지하는 것이 중요해요.', lv3: '(W)\'피의 사냥\'으로 이동 속도를 높여 접근하되 아이번의 (Q)\'덩굴뿌리\' 속박을 피하는 것이 핵심이에요. 진입 후에는 (E)\'원시의 포효\'를 켜서 (E)\'보호의 씨앗\' 폭발 피해를 줄이고 포효로 상대를 공포에 빠뜨려 딜교환을 마무리하세요. 상대의 속박 스킬이 빠진 타이밍을 노려 공격적으로 움직여요.', lv6: '(R)\'무한의 구속\'을 사용해 (R)\'데이지!\'를 무시하고 아이번 본체를 직접 제압하며 처치 기회를 노리세요. 다만 (R)\'데이지!\'의 공격으로 공중에 뜰 수 있으니 진입 각도를 신중하게 결정해야 해요. 라인을 밀어 넣고 정글러를 호출하면 아이번이 도망치기 어렵게 만들 수 있어요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 추천해요. 마법 저항력을 높여 아이번의 마법 피해를 줄이고 생명선 보호막으로 생존력을 높이기 위해서예요.', spell: '점멸과 점화를 추천해요. 낮은 체력의 아이번을 확실하게 마무리하고 피해를 극대화하기 위해서예요.' },
    '아지르': { lv1: '아지르는 (Q)\'사막의 맹습\'으로 모래 병사를 보내 견제하며 사거리가 길어요. 1~2레벨에는 병사가 지나가는 길을 비켜서고 (P)\'끝없는 허기\'로 체력을 관리하며 미니언에 집중하세요. 병사가 빠진 틈에 (Q)\'야수의 송곳니\'로 붙을 타이밍을 보세요.', lv3: '아지르는 (W)\'일어나라!\'로 세운 병사 범위 안에서 공격하니 병사 위치를 보고 (Q)\'야수의 송곳니\'로 아지르 본체를 물어 접근하세요. 붙은 뒤에는 (E)\'원시의 포효\'로 피해를 줄이고 공포를 맞혀 딜교환을 이어가세요. 아지르는 (E)\'신기루\'로 병사 쪽으로 빠져나가니 이 스킬이 빠졌을 때 진입하면 더 오래 붙어 있을 수 있어요.', lv6: '아지르가 (R)\'황제의 진영\'을 쓰기 전에 (R)\'무한의 구속\'으로 먼저 제압해 흐름을 끊으세요. (R)\'황제의 진영\'은 적을 밀어내니 이미 쓴 뒤라면 병사들이 사라진 뒤에 추격하세요. (E)\'신기루\' 사용 여부를 확인하고 궁극기를 사용하는 것이 중요해요.', item: '헤르메스의 발걸음과 갈라진 하늘을 가요. 아지르의 마법 피해를 견디고 전투 지속력을 높이기 위해서예요.', spell: '점멸과 점화를 추천해요. 점멸로 병사들 사이를 파고들고 점화로 마무리 피해를 넣어 킬을 내요.' },
    '아칼리': { lv1: '아칼리가 (Q)\'오연투척검\'으로 둔화를 걸며 견제하려 하니 거리를 조절하며 미니언을 챙기세요. 아칼리의 (P)\'암살자의 표식\' 원 경계 근처에서 싸우면 강화 평타를 맞을 수 있으니 주의해야 해요. (Q)\'야수의 송곳니\'로 체력을 회복하며 버티는 것이 중요해요.', lv3: '아칼리가 (E)\'표창곡예\'로 돌진해 들어오면 (E)\'원시의 포효\'를 재사용하여 공포를 걸어 대응하세요. (W)\'황혼의 장막\' 안에서는 (Q)\'야수의 송곳니\'로 아칼리를 대상으로 지정할 수 없지만 (E)\'원시의 포효\'의 공포는 범위 효과라 연막 안에서도 걸려요. 아칼리가 (Q)\'오연투척검\'을 맞히고 들어오는 타이밍에 (Q)\'야수의 송곳니\'로 맞서세요.', lv6: '아칼리가 (R)\'무결처형\'으로 진입할 때 (R)\'무한의 구속\'을 사용해 제압하면 역공이 가능해요. (W)\'황혼의 장막\' 안에서는 아칼리를 대상으로 지정할 수 없으니 연막이 걷히거나 아칼리가 공격해 모습이 드러날 때를 노리세요. 내 체력이 낮아지면 (P)\'끝없는 허기\'의 회복량이 커지니 과감하게 맞서 싸우세요.', item: '첫 코어로 갈라진 하늘을 가서 전투 지속력을 높이세요. 신발은 아칼리의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 선택해요.', spell: '점멸과 탈진을 추천해요. 탈진으로 아칼리의 순간적인 피해량을 낮추면 전투를 더 길게 이어갈 수 있어요.' },
    '아크샨': { lv1: '(Q)\'복수의 부메랑\' 견제를 견디며 미니언을 챙기세요. 체력이 낮아지면 (P)\'끝없는 허기\' 회복력을 믿고 딜교환을 시도하되, (Q)\'야수의 송곳니\'로 진입할 때 상대의 거리 조절에 주의하세요.', lv3: '(E)\'영웅의 비상\'으로 진입하는 아크샨에게 (E)\'원시의 포효\'를 켜서 피해를 줄이세요. 상대의 갈고리총이 빠진 타이밍에 (Q)\'야수의 송곳니\'로 물어뜯어 딜교환을 유도하세요.', lv6: '(R)\'무한의 구속\'으로 진입해 제압한 뒤 빠르게 체력을 깎으세요. 다만 (R)\'인과응보\'의 마무리 피해가 강력하므로 체력이 너무 낮을 때는 무리하게 진입하지 마세요.', item: '판금 장화와 칠흑의 양날 도끼를 추천해요. 판금 장화로 기본 공격 피해를 줄이고 칠흑의 양날 도끼로 체력을 보강하며 챔피언의 방어력을 깎아 피해를 늘리세요.', spell: '점멸과 순간이동을 추천해요. 점멸로 (R)\'무한의 구속\' 각을 만들고 순간이동으로 라인 복귀와 합류를 챙기세요.' },
    '아트록스': { lv1: '아트록스의 (Q)\'다르킨의 검\'은 끝부분에 맞으면 에어본이 발생하니 사거리를 잘 확인하며 피하세요. 1~2레벨에는 (P)\'사신 태세\'를 활용한 아트록스의 평타와 회복을 조심하며 미니언을 받아먹으세요. (Q)\'야수의 송곳니\'를 사용하여 체력을 관리하며 버티는 것이 중요해요.', lv3: '아트록스가 (W)\'지옥사슬\'을 사용하면 중앙으로 끌려가지 않도록 즉시 범위 밖으로 움직이세요. 아트록스가 (Q)\'다르킨의 검\'을 휘두르는 타이밍에 (E)\'원시의 포효\'를 사용하여 피해를 감소시키고 공포를 걸어야 해요. 이후 (Q)\'야수의 송곳니\'로 들어가서 딜교환을 하세요.', lv6: '아트록스가 (R)\'세계의 종결자\'를 켜면 회복량이 늘어나니 정면 대결을 피하며 거리를 유지하세요. 체력이 낮은 아트록스에게 (R)\'무한의 구속\'을 사용하여 제압한 뒤 (Q)\'야수의 송곳니\'로 적중시키면 킬을 노릴 수 있어요. 아트록스가 (E)\'파멸의 돌진\'으로 도망치지 못하게 주의하세요.', item: '몰락한 왕의 검으로 전투 지속력을 높이세요. 판금 장화를 구매하여 아트록스의 기본 공격 피해를 줄이는 것이 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 아트록스의 (P)\'사신 태세\'와 (E)\'파멸의 돌진\' 회복을 억제하세요.' },
    '암베사': { lv1: '암베사가 (P)\'용사냥개의 발걸음\'으로 스킬 사용 후 돌진하며 강화 평타를 쓰니 거리를 잘 조절해야 해요. (Q)\'교활한 휩쓸기\'의 범위 끝에 맞지 않도록 주의하며 (Q)\'야수의 송곳니\'로 체력을 회복하며 버티세요. 암베사의 돌진 타이밍을 읽고 (E)\'원시의 포효\'로 피해를 줄이며 대응하세요.', lv3: '암베사가 (W)\'배척\'을 준비하는 동안 피해를 받으면 내려치는 피해가 커지니 보호막이 켜진 동안에는 (Q)\'야수의 송곳니\'를 아끼세요. (E)\'찢어 가르기\'의 둔화에 걸리면 (E)\'원시의 포효\'를 재사용해 공포를 걸고 거리를 벌리세요. 암베사의 스킬이 빠진 뒤 (W)\'피의 사냥\'의 속도를 이용해 (Q)\'야수의 송곳니\'로 딜교환을 하세요.', lv6: '암베사의 (R)\'공개 처형\'은 일직선상에서 가장 멀리 있는 적 챔피언에게 저지 불가 상태로 순간이동해 제압하니 멀리 떨어져 있어도 안심하지 마세요. 제압당하면 스킬을 쓸 수 없으니 체력이 낮을 때는 암베사와 일직선상에 서지 않도록 위치를 조절하세요. 암베사의 체력이 낮아지면 (W)\'피의 사냥\'의 가속을 받아 (R)\'무한의 구속\'으로 킬각을 잡으세요.', item: '암베사는 물리 피해 위주이므로 판금 장화로 기본 공격 피해를 줄이세요. 첫 코어 아이템은 몰락한 왕의 검을 가서 (P)\'끝없는 허기\'와 함께 생명력 흡수로 유지력을 높이세요.', spell: '점멸과 점화를 추천해요. 점화로 암베사의 체력을 빠르게 깎아 마무리하거나 교전에서 압박을 더하세요.' },
    '애니비아': { lv1: '애니비아는 (Q)\'냉기 폭발\'로 멀리서 견제하며 기절을 노려요. 구체가 터지는 지점을 피해 옆으로 움직이며 (Q)\'야수의 송곳니\'로 진입할 타이밍을 보세요. 초반에는 무리하게 붙기보다 미니언을 챙기며 체력을 보존하세요.', lv3: '(E)\'원시의 포효\'를 사용해 애니비아의 피해를 줄이면서 다가가세요. 애니비아의 (Q)\'냉기 폭발\'이 빠진 것을 확인하고 (Q)\'야수의 송곳니\'로 물면 좋아요. (W)\'결정화\' 벽은 진입 경로를 막을 수 있으니 벽이 녹은 뒤나 벽을 쓴 것을 확인한 뒤에 들어가세요.', lv6: '(R)\'무한의 구속\'으로 애니비아를 제압한 뒤 (Q)\'야수의 송곳니\'를 섞어 빠르게 몰아붙이세요. (P)\'환생\'으로 알이 된 적을 빠르게 처치하고 정글러와 함께 라인을 압박하세요. (R)\'얼음 폭풍\' 안에서는 둔화 때문에 진입이 어려우니 장판 밖에서 싸우는 것이 좋아요.', item: '맬모셔스의 아귀를 첫 코어로 가서 애니비아의 마법 피해를 버텨내세요. 신발은 마법 저항력과 군중 제어 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점멸로 (Q)\'냉기 폭발\'을 피하거나 거리를 좁히세요. 점화는 지속 피해로 체력을 빠르게 깎아 압박해요.' },
    '야스오': { lv1: '야스오가 (Q)\'강철 폭풍\'을 사용하여 중첩을 쌓으면 띄워질 수 있으니 주의하며 거리를 조절하세요. (Q)\'야수의 송곳니\'를 사용하여 짧게 물면 피해를 입히면서 동시에 체력을 회복할 수 있어요. 야스오가 (E)\'질풍검\'으로 미니언 사이를 빠르게 움직이며 압박하는 구간에서는 무리하게 맞서지 마세요.', lv3: '야스오의 (W)\'바람 장막\'은 투사체만 막으니 도약하는 (Q)\'야수의 송곳니\'와 (E)\'원시의 포효\'는 그대로 쓸 수 있어요. (E)\'원시의 포효\'를 사용하여 피해를 줄인 뒤 야스오에게 공포를 입히면 딜교환을 주도할 수 있어요. (E)\'질풍검\'으로 들어오는 야스오를 (Q)\'야수의 송곳니\'로 꽉 물어 체력을 회복하며 맞받아치세요.', lv6: '야스오가 (Q)\'강철 폭풍\'으로 띄우는 순간 (R)\'최후의 숨결\'이 들어올 수 있으니 띄워지기 전에 (E)\'원시의 포효\'를 사용하세요. (R)\'무한의 구속\'은 야스오를 제압할 수 있는 강력한 기술이니 야스오의 (E)\'질풍검\' 돌진을 예측하여 사용하세요. 라인을 밀어 넣은 뒤에는 야스오가 (R)\'최후의 숨결\'을 쓰지 못하도록 정글러와 함께 움직이세요.', item: '판금 장화와 몰락한 왕의 검을 구매하세요. 판금 장화는 야스오의 기본 공격 피해를 줄여주고, 몰락한 왕의 검은 전투 시 생명력 흡수를 도와줘요.', spell: '점멸과 점화를 추천해요. (R)\'무한의 구속\'으로 야스오를 제압한 뒤 점화로 마무리하면 킬을 가져오기 쉬워요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'으로 평타 사거리를 늘려 견제하며 (P)\'바위 피부\'로 점점 단단해져요. 1~2레벨에는 무리하게 붙기보다 (Q)\'야수의 송곳니\'로 짧게 치고 빠지며 체력을 관리하세요. 오공이 평타로 견제할 때 거리 조절을 하며 (P)\'끝없는 허기\'의 회복 효율이 높아지는 낮은 체력 구간을 이용해 버티세요.', lv3: '(E)\'근두운 급습\'으로 빠르게 붙는 오공의 진입에 맞춰 (E)\'원시의 포효\'를 켜서 피해를 줄이고 공포로 밀어내세요. 오공이 (W)\'분신 전사\'를 쓰고 사라지면 진짜 위치를 확인한 뒤 (Q)\'야수의 송곳니\'로 물어 체력을 회복하세요. 상대의 돌진기가 빠진 뒤 (W)\'피의 사냥\'의 공격 속도 증가를 활용해 짧은 딜교환을 반복하세요.', lv6: '오공의 (R)\'회전격\'에 맞으면 공중에 떠서 아무것도 못 하니 정면에서 맞서지 말고 옆으로 피하세요. (R)\'회전격\'이 빠진 타이밍에 (R)\'무한의 구속\'으로 제압하여 확실하게 킬각을 잡으세요. (W)\'피의 사냥\'으로 이동 속도를 높여 (R)\'무한의 구속\'의 도약 거리를 늘리면 오공의 도주 경로를 차단하기 편해요.', item: '갈라진 하늘을 첫 코어로 가서 체력을 높이고 공격 시 체력 회복으로 버티세요. 신발은 오공의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (W)\'피의 사냥\'으로 빠르게 접근한 뒤 점화로 피해를 입혀 확실하게 마무리하세요.' },
    '오로라': { lv1: '오로라는 (Q)\'이중 저주\'를 사용해 멀리서 견제하며 (P)\'영혼 방호술\'로 체력을 회복해요. 저주를 다시 불러들일 때 에너지가 오로라 쪽 경로로 돌아오니 그 길에서 비켜서고, 맞더라도 (E)\'원시의 포효\'를 켜서 피해를 줄이세요.', lv3: '오로라가 (E)\'마법의 문\'으로 둔화를 걸고 뒤로 도망가면 (Q)\'야수의 송곳니\'로 거리를 좁히세요. (E)\'원시의 포효\'의 지속시간이 끝나기 전에 재사용하여 공포를 맞히면 딜교환을 이끌어낼 수 있어요.', lv6: '오로라의 (R)\'세계의 경계\' 영역 안에서는 오로라가 이동하기 쉬우니 (R)\'무한의 구속\'으로 제압하여 대응하세요. (W)\'장막 너머로\'로 투명해진 오로라를 쫓기보다는 (W)\'피의 사냥\'의 이동 속도를 활용해 위치를 찾으세요.', item: '첫 코어로 갈라진 하늘을 선택해 전투 지속력을 높이세요. 신발은 오로라의 마법 피해를 견디기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 오로라가 (P)\'영혼 방호술\'로 영혼을 모아 체력을 회복할 때 점화를 사용하여 회복량을 줄이세요.' },
    '오른': { lv1: '오른은 (P)\'간이 대장간\' 덕분에 방어력과 마법 저항력이 높아 초반부터 단단해요. (Q)\'용암 균열\'의 둔화와 기둥 위치를 피해 짧게 공격하고 빠르게 빠지세요. 1~2레벨에는 무리하게 붙기보다 (P)\'끝없는 허기\'를 활용해 체력을 관리하며 기회를 보세요.', lv3: '오른이 (E)\'화염 돌진\'으로 벽에 밀어붙이려 하면 벽에서 떨어져 공중으로 띄워지는 것을 피하세요. (W)\'불꽃 풀무질\'의 마지막 타격에 맞아 불안정 상태가 되기 전에 (E)\'원시의 포효\'로 피해를 줄이고 공포를 걸어 거리를 벌리세요. 상대의 주요 CC기가 빠진 뒤 (Q)\'야수의 송곳니\'로 진입해 끈질기게 공격하세요.', lv6: '(R)\'대장장이 신의 부름\'의 정령 진행 방향을 확인하고, 정령에 부딪혀 공중으로 띄워지지 않도록 주의하세요. (W)\'피의 사냥\'으로 이동 속도를 높인 뒤 (R)\'무한의 구속\'으로 진입해 상대를 제압하고 체력을 회복하세요. 오른은 라인 유지력이 좋으므로 억지로 킬을 내기보다 정글러를 불러 함께 압박하는 것이 좋아요.', item: '몰락한 왕의 검과 판금 장화를 추천해요. 체력이 높은 오른을 상대하기 위해 생명력 흡수가 있는 몰락한 왕의 검이 좋으며, 판금 장화로 기본 공격 피해를 줄이세요.', spell: '점멸과 순간이동을 추천해요. 오른은 매우 단단해 한 번의 교전으로 잡기 어려우니 순간이동으로 라인 복귀를 빠르게 하세요.' },
    '올라프': { lv1: '올라프가 (Q)\'역류\'를 던져 방어력을 깎고 둔화를 걸면 이동 속도가 느려져 위험해요. 도끼를 피하거나 올라프가 도끼를 주우러 오는 타이밍에 (Q)\'야수의 송곳니\'로 짧게 교환하고 빠지세요. 체력이 낮아질수록 (P)\'끝없는 허기\'로 회복량이 늘어나니 체력 관리에 주의하며 대응하세요.', lv3: '올라프가 (W)\'버티기\'를 켜서 보호막과 공격 속도를 얻었을 때는 정면 승부를 피하세요. (E)\'무모한 강타\'의 고정 피해가 들어올 때 (E)\'원시의 포효\'를 켜서 피해를 줄이고, 포효의 공포 효과로 올라프의 추격을 끊어내세요. (Q)\'야수의 송곳니\'를 짧게 써서 올라프가 도끼를 줍는 동선에 맞춰 교환하세요.', lv6: '올라프가 (R)\'라그나로크\'를 사용하면 이동 불가와 이동 방해 효과를 정화하고 면역이 되니 그동안은 군중 제어에 기대지 말고 거리를 유지하세요. 궁극기가 켜진 동안에는 무리하게 싸우지 말고 지속시간이 끝나기를 기다리세요. 궁극기가 종료된 직후 (R)\'무한의 구속\'으로 제압해 처리하고, 정글러가 올 때는 (W)\'피의 사냥\'으로 빠르게 합류하세요.', item: '판금 장화와 몰락한 왕의 검을 추천해요. 판금 장화로 올라프의 기본 공격 피해를 줄이고, 몰락한 왕의 검의 생명력 흡수로 유지력을 높이세요.', spell: '점멸과 점화를 추천해요. 올라프가 (P)\'광전사의 분노\'로 얻는 생명력 흡수가 매우 강력하므로 점화의 치유 감소 효과로 이를 억제해야 해요.' },
    '요네': { lv1: '요네가 (Q)\'필멸의 검\' 중첩을 쌓아 돌풍으로 띄우려 할 때 옆으로 피하며 거리 조절을 하세요. (Q)\'야수의 송곳니\'로 짧게 진입해 피해를 입히고 빠르게 빠지며 체력을 회복하세요. (P)\'사냥꾼의 길\' 때문에 평타 교환을 길게 가져가는 것은 피하세요.', lv3: '요네가 (E)\'영혼해방\'을 쓰고 진입하면 무리하게 쫓지 말고 육신이 있는 위치에서 (E)\'원시의 포효\'를 준비하세요. (W)\'영혼 가르기\'의 보호막이 생성된 동안에는 공격을 멈추고 보호막이 사라진 뒤에 다시 교환하세요. (Q)\'필멸의 검\'의 돌풍 타이밍에 맞춰 (E)\'원시의 포효\'로 공포를 걸어 흐름을 끊으세요.', lv6: '요네의 (R)\'운명봉인\'에 끌려와 공중에 뜨면 스킬을 쓸 수 없으니 그 전에 (E)\'원시의 포효\'를 미리 켜서 피해를 줄이세요. (E)\'영혼해방\'이 끝나고 원래 위치로 돌아가는 순간에 맞춰 (R)\'무한의 구속\'을 사용하면 확실하게 맞힐 수 있어요. 라인을 당겨 두고 요네가 들어올 때 정글러와 함께 덮치면 정리가 쉬워요.', item: '몰락한 왕의 검을 가서 생명력 흡수로 지속 전투력을 높이세요. 신발은 요네의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 요네의 체력이 낮을 때 점화의 추가 피해로 빠르게 마무리하세요.' },
    '요릭': { lv1: '요릭은 (Q)\'최후의 의식\'으로 미니언을 처치해 무덤을 쌓아야 해요. (Q)\'야수의 송곳니\'로 진입해 빠르게 체력을 깎으며 (P)\'끝없는 허기\'의 회복력으로 버티세요. 무덤이 쌓이기 전에 짧은 교환을 반복하며 요릭의 체력을 낮추는 것이 중요해요.', lv3: '(E)\'애도의 안개\'에 맞으면 방어력이 깎이고 망령들이 몰려오니 최대한 피하고, 맞았다면 (E)\'원시의 포효\'로 피해를 줄이세요. (W)\'망자의 진\' 벽은 공격하면 부서지니 갇혔다면 평타로 빠르게 부수고 나오세요. 요릭의 (Q)\'최후의 의식\'이 빠진 동안 적극적으로 들어가세요.', lv6: '요릭이 (R)\'군도의 장송곡\'으로 마녀를 소환하면 소환물 피해가 극심해지니 (R)\'무한의 구속\'으로 요릭을 제압해 마녀의 추가 피해 타이밍을 끊으세요. (W)\'피의 사냥\'으로 가속을 얻어 진입하고 마녀가 있는 곳에서 너무 오래 싸우지 마세요. 마녀가 라인을 밀 때 포탑 근처에서 (Q)\'야수의 송곳니\'로 버티며 받아먹으세요.', item: '삼위일체로 공격력과 체력을 챙겨 요릭과의 지속전에 대비하세요. 신발은 요릭의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (Q)\'최후의 의식\'으로 회복하는 요릭의 체력을 점화로 억제하고 확실하게 마무리하세요.' },
    '우디르': { lv1: '우디르가 (Q)\'야생 발톱\' 태세로 강화된 평타를 치러 오면 거리를 조절하며 대응하세요. 1~2레벨에는 우디르의 (E)\'불길 쇄도\' 기절을 피하는 것이 중요하며 (Q)\'야수의 송곳니\'를 활용해 체력을 회복하며 싸워야 해요. 우디르가 태세를 바꾸며 들어오는 타이밍을 잘 살펴야 해요.', lv3: '우디르가 (W)\'강철 갑옷\'으로 보호막을 얻었을 때는 딜교환을 잠시 멈추고 기다리세요. 우디르가 (E)\'불길 쇄도\'를 재사용해 이동 불가 효과에 면역이 된 상태에서는 (E)\'원시의 포효\'로 공포를 걸기 어려우니 주의해야 해요. 우디르의 면역이 끝난 뒤에 (Q)\'야수의 송곳니\'를 사용해서 싸우세요.', lv6: '우디르가 (R)\'날개 돋친 폭풍\'을 사용해 둔화를 걸면 무리하게 진입하지 말고 거리를 벌리세요. 우디르가 (E)\'불길 쇄도\'의 면역 효과를 쓰고 난 직후에 (R)\'무한의 구속\'으로 제압을 시도하세요. (R)\'무한의 구속\' 사용 중에는 우디르의 체력 회복을 고려해 확실한 킬각을 잡아야 해요.', item: '몰락한 왕의 검을 첫 코어로 가서 전투 지속력을 높이세요. 신발은 우디르의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 우디르의 (W)\'강철 갑옷\' 회복 효과를 줄이며 승부를 보세요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'을 발사해 둔화를 걸며 견제하므로 폭약이 떨어지는 위치를 잘 피하며 미니언을 챙기세요. 우르곳의 견제가 강할 때는 거리를 유지하며 (Q)\'야수의 송곳니\'로 짧게 딜교환하고 빠지는 것이 좋아요. (W)\'피의 사냥\'으로 체력이 낮은 적을 빠르게 감지할 수 있으니 이를 활용해 전투 타이밍을 잡으세요.', lv3: '우르곳이 (W)\'심판의 원\'을 켜고 기관총을 사격할 때는 사거리 밖으로 벗어나 피해를 피하세요. 우르곳의 (E)\'경멸\'에 맞으면 뒤로 던져지니 돌진하는 방향을 미리 파악하고 (E)\'원시의 포효\'를 사용하여 피해를 줄이거나 공포를 활용하세요. 우르곳이 (Q)\'부식성 폭약\'을 맞힌 직후에는 (W)\'심판의 원\' 연계가 강력하니 주의해야 해요.', lv6: '우르곳의 (R)\'불사의 공포\'가 꽂히면 체력이 낮을 때 처형당할 수 있으니 섬광탄을 맞았다면 즉시 거리를 벌리세요. 우르곳이 처형을 시도하기 전에 (R)\'무한의 구속\'으로 먼저 제압하는 것이 중요해요. 라인 관리 시에는 우르곳의 궁극기 사거리 안에 갇히지 않도록 적절한 위치를 유지하며 정글러를 부르세요.', item: '굶주린 히드라를 첫 코어로 가서 전투 지속력을 높이세요. 신발은 물리 피해가 주력인 우르곳을 상대하기 위해 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 마무리 피해를 더해 (R)\'무한의 구속\' 연계 시 확실하게 킬을 낼 수 있어요.' },
    '이렐리아': { lv1: '이렐리아는 (Q)\'칼날 쇄도\'로 미니언을 타고 들어오며 체력을 회복하니 미니언 체력을 잘 확인하세요. (Q)\'야수의 송곳니\'를 활용해 이렐리아의 접근을 끊거나 맞받아치며 체력을 관리해야 해요. 이렐리아의 스택이 쌓이기 전에 거리를 조절하며 대응하세요.', lv3: '이렐리아의 (E)\'쌍검협무\'가 날아오는 방향을 보고 피해 기절을 피하는 것이 중요해요. 이렐리아가 (W)\'저항의 춤\'을 사용하여 피해를 감소시킬 때는 (Q)\'야수의 송곳니\'를 아끼며 타이밍을 노리세요. (E)\'원시의 포효\'를 미리 사용해 이렐리아의 진입 피해를 줄이고 공포로 흐름을 끊으세요.', lv6: '이렐리아가 (R)\'선봉진격검\'으로 결계를 만들면 둔화에 걸리니 주의하며 거리를 유지하세요. 이렐리아의 진입 타이밍에 (R)\'무한의 구속\'을 사용하여 제압하면 딜교환을 강제로 멈출 수 있어요. (P)\'끝없는 허기\' 덕분에 낮은 체력에서도 역전이 가능하니 정글러의 개입을 유도하며 싸우세요.', item: '몰락한 왕의 검을 첫 코어로 가서 생명력 흡수로 버티며 싸우세요. 신발은 이렐리아의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 이렐리아의 (Q)\'칼날 쇄도\' 체력 회복 효과를 줄여 킬각을 잡으세요.' },
    '일라오이': { lv1: '일라오이는 (P)\'고대신의 예언자\'로 벽 근처에 촉수를 소환해 공격하니 벽에서 멀리 떨어져서 싸우세요. 1~2레벨에는 일라오이가 (Q)\'촉수 강타\'를 사용할 때 거리를 조절하고, 적의 체력이 낮아지면 (Q)\'야수의 송곳니\'로 진입해 피해를 주고 체력을 회복하세요. 촉수가 없는 평지에서 짧게 딜교환을 하는 것이 좋아요.', lv3: '(E)\'영혼의 시험\'에 맞으면 영혼이 분리되어 일라오이가 영혼을 때릴 때 피해를 입으니, 영혼과 너무 멀어지지 않도록 주의하세요. (W)\'혹독한 가르침\'으로 도약해 들어오는 일라오이에게 (E)\'원시의 포효\'를 켜서 피해를 감소시킨 뒤 공포로 밀어내며 빠져나오세요. 상대의 (E)\'영혼의 시험\'이 빠진 타이밍에 (Q)\'야수의 송곳니\'로 진입해 빠르게 공격하고 나오세요.', lv6: '일라오이가 (R)\'믿음의 도약\'을 쓰면 주변에 많은 촉수가 생겨 피해가 극심하니, 궁극기 범위 밖으로 빠르게 벗어나세요. 일라오이의 궁극기가 끝난 뒤 체력이 낮아진 틈을 타 (R)\'무한의 구속\'으로 제압하고 (W)\'피의 사냥\'의 공격 속도 증가 효과를 이용해 마무리하세요. 라인을 당겨 정글러와 함께 덮치면 일라오이가 촉수를 활용하기 전에 제압할 수 있어요.', item: '칠흑의 양날 도끼를 첫 코어로 선택해 체력을 높이고 챔피언에게 피해를 줄 때마다 방어력을 깎아 일라오이의 단단함을 뚫으세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 고정 피해를 이용해 체력이 낮아진 일라오이를 확실하게 마무리하세요.' },
    '자크': { lv1: '1~2레벨에는 (Q)\'야수의 송곳니\'를 사용하여 자크의 체력을 깎으며 맞딜을 하세요. 자크가 (Q)\'탄성 주먹\'으로 붙잡으려 할 때 거리를 조절하고, 자크가 (P)\'세포 분열\' 조각을 모으지 못하게 압박하세요.', lv3: '자크가 (E)\'새총 발사\'로 돌진하기 전에 (E)\'원시의 포효\'를 사용하여 피해를 줄이거나 공포를 맞히세요. 자크가 (Q)\'탄성 주먹\'을 사용한 직후에 (Q)\'야수의 송곳니\'로 거리를 좁히며 딜교환을 하고, 자크가 (W)\'불안정 물질\'로 조각을 뿌린다면 조각을 줍지 못하게 압박하세요.', lv6: '자크가 (R)\'바운스!\'를 사용하여 공중으로 띄우려 할 때 (R)\'무한의 구속\'으로 먼저 제압하여 흐름을 끊으세요. 자크가 (P)\'세포 분열\'로 갈라지면 조각이 다시 합쳐지기 전에 평타로 조각을 처치해 부활을 막으세요. 라인을 빠르게 밀어 넣어 자크가 조각을 주우러 가기 어렵게 만드세요.', item: '첫 코어로 갈라진 하늘을 선택해 전투 지속력을 높이세요. 신발은 자크의 마법 피해와 군중 제어 효과를 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 자크가 (P)\'세포 분열\'로 부활하기 전에 빠르게 처치하여 킬을 가져오기 위해서예요.' },
    '자헨': { lv1: '자헨은 (Q)\'다르킨의 글레이브\'로 연속 공격하며 체력을 회복하므로 초반에 무리한 평타 교환은 피하세요. (Q)\'야수의 송곳니\'로 적에게 접근해 피해를 입히고 체력을 회복하며 미니언을 챙기세요. 자헨의 결심 중첩이 쌓이지 않도록 거리를 조절하며 대응해요.', lv3: '자헨이 (W)\'공포의 귀환\'으로 적을 끌어당기려 하면 옆으로 이동해 피하세요. 자헨이 (E)\'찬란한 쇄도\'로 돌진해 올 때 (E)\'원시의 포효\'를 사용하여 피해를 줄이고 공포를 입히세요. 자헨의 (Q)\'다르킨의 글레이브\' 재사용 공격으로 공중에 뜨기 전에 (Q)\'야수의 송곳니\'를 활용해 교환하세요.', lv6: '자헨이 (R)\'단호한 판결\'로 날아오르는 동안에는 낙하 지점을 피해 위치를 잡으세요. 자헨의 결심이 가득 차서 부활할 수 있으니 (R)\'무한의 구속\'으로 제압한 뒤 빠르게 처치해야 해요. 자헨이 궁극기를 사용하여 피해를 줄이는 동안에는 무리하게 진입하지 마세요.', item: '몰락한 왕의 검을 첫 코어로 가서 전투 지속력을 높이세요. 신발은 자헨의 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 자헨은 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'로 체력을 회복하니 점화의 치유 감소가 효과적이에요.' },
    '잭스': { lv1: '잭스가 (Q)\'도약 공격\'으로 거리를 좁히며 (W)\'무기 강화\' 평타를 치려고 하면 뒤로 물러나며 거리를 조절하세요. 1~2레벨에는 (Q)\'야수의 송곳니\'로 잭스의 체력을 깎으며 맞딜을 준비하는 것이 좋아요. 잭스의 공격 속도가 (P)\'가차없는 맹공\'으로 인해 높아지기 전에 짧게 딜교환을 하고 빠지세요.', lv3: '잭스가 (E)\'반격\'을 사용하면 기본 공격이 모두 회피되고 끝나면 주변 적이 기절하니 반격 중에는 기본 공격을 멈추고 범위 밖으로 비켜서세요. (E)\'반격\'이 끝난 뒤에 (E)\'원시의 포효\'를 재사용하여 공포를 입히고 (Q)\'야수의 송곳니\'로 체력을 회복하며 싸우세요. (Q)\'도약 공격\'이 빠진 상태에서 (W)\'피의 사냥\'의 이동 속도 증가를 활용해 좋은 위치를 잡으세요.', lv6: '잭스가 (R)\'무기의 달인\'을 사용하면 방어력과 마법 저항력이 크게 오르니 정면 승부는 피하는 것이 좋아요. 잭스의 체력이 낮아졌을 때 (R)\'무한의 구속\'으로 제압을 걸어 지속적인 피해를 입히고 체력을 회복하세요. (E)\'원시의 포효\'를 적절히 사용하여 잭스의 돌진을 방해하며 정글러의 개입을 기다리세요.', item: '첫 코어로 굶주린 히드라를 가서 생명력 흡수와 높은 공격력을 확보하세요. 신발은 잭스의 기본 공격 피해를 줄여주는 판금 장화가 적합해요.', spell: '점멸과 점화를 추천해요. 점화로 잭스를 마무리하는 피해를 더하고 킬각을 잡는 데 도움을 줘요.' },
    '제이스': { lv1: '캐논 형태의 (Q)\'전격 폭발\'은 적을 맞히면 그 자리에서 폭발하니 미니언 뒤에 서되 폭발 범위에 함께 휘말리지 않게 간격을 두세요. 제이스가 거리를 벌리며 견제할 때 무리하게 맞서지 말고 (Q)\'야수의 송곳니\'로 체력을 관리하며 다음 기회를 기다리세요.', lv3: '제이스가 해머 형태로 (E)\'천둥 강타\'를 사용하여 밀어낼 수 있으니 거리를 적절히 조절하며 접근하세요. 제이스가 스킬을 사용한 직후에 (E)\'원시의 포효\'를 켜고 들어가서 피해를 줄이며 (Q)\'야수의 송곳니\'로 붙는 것이 중요해요.', lv6: '제이스가 (R)\'머큐리 캐논\'으로 사거리를 늘려 도망가려 하면 (R)\'무한의 구속\'을 사용하여 강제로 제압하세요. 제이스가 해머 형태로 바꿔 (Q)\'하늘로!\'로 뛰어들면 (E)\'원시의 포효\'를 켜서 피해를 줄이고 공포로 맞받아치세요.', item: '삼위일체를 첫 코어로 사용하여 전투를 지속하세요. 신발은 제이스의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 제이스의 체력이 낮아졌을 때 점화를 사용하여 확실하게 킬을 노리세요.' },
    '초가스': { lv1: '초가스가 (Q)\'파열\'을 사용해 공중에 띄우려 할 때 원 밖으로 빠르게 벗어나세요. (E)\'날카로운 가시\'의 둔화가 걸리면 다가가기 힘드니 평타 거리 조절에 신경 쓰세요. (Q)\'야수의 송곳니\'로 짧게 들어가 피해를 입히고 빠르게 빠져나오며 체력을 관리해요.', lv3: '(W)\'흉포한 울부짖음\'에 침묵되면 스킬을 쓸 수 없으니 초가스가 비명을 지른 뒤에 진입하세요. (Q)\'파열\'이 빗나간 순간 (Q)\'야수의 송곳니\'로 붙어 공격하고 (E)\'원시의 포효\'로 피해를 줄이며 버티세요. (E)\'원시의 포효\'의 공포 효과로 초가스의 공격 흐름을 끊어 딜교환을 이끌어내세요.', lv6: '(R)\'포식\'의 고정 피해로 순식간에 처치당할 수 있으니 체력이 낮을 때는 무리하게 붙지 마세요. 초가스가 (Q)\'파열\'을 헛방 쳤을 때 (R)\'무한의 구속\'으로 도약해 제압하며 체력을 회복하세요. (W)\'피의 사냥\'으로 이동 속도를 높여 정글러의 개입을 빠르게 돕거나 기습적인 킬각을 잡으세요.', item: '몰락한 왕의 검을 첫 코어로 가서 체력이 높은 초가스에게 효율적인 피해를 입히세요. 신발은 마법 저항력을 높이고 침묵 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'육식\'을 통한 초가스의 체력 회복을 방해하고 마무리 피해를 주세요.' },
    '카밀': { lv1: '1~2레벨에는 카밀이 (Q)\'정확성 프로토콜\'의 두 번째 강화 평타로 고정 피해를 입히려 할 때 거리를 조절하세요. (P)\'적응형 방어 체계\' 보호막이 생성된 상태에서 계속 싸우기보다 보호막이 사라진 뒤에 기본 공격으로 압박하세요. (Q)\'야수의 송곳니\'를 짧게 사용하여 빠르게 체력을 회복하며 딜교환하세요.', lv3: '카밀이 (E)\'갈고리 발사\'로 도약해 들어올 때 (E)\'원시의 포효\'를 켜서 피해를 줄이고, 착지 후 포효로 카밀을 공포 상태로 만들어 흐름을 끊으세요. (W)\'전술적 휩쓸기\'의 바깥쪽 절반에 맞으면 둔화되고 상대가 회복하니, 최대한 안쪽으로 파고들어 대응하세요. (W)\'피의 사냥\'으로 이동 속도가 올랐을 때 (Q)\'야수의 송곳니\'로 붙어 짧게 치고 빠지세요.', lv6: '(R)\'마법공학 최후통첩\'에 갇히면 탈출할 수 없으니, 카밀이 궁극기를 쓰기 전에 (R)\'무한의 구속\'으로 먼저 제압해 흐름을 끊는 것이 중요해요. 카밀이 (E)\'갈고리 발사\'를 사용해 벽을 넘으며 정글러와 함께 습격할 수 있으니 벽 근처에서는 주의하세요. 체력이 낮은 적을 향해 (W)\'피의 사냥\' 속도를 이용해 빠르게 접근해 킬각을 잡으세요.', item: '삼위일체를 첫 코어로 선택해 공격 속도와 체력을 보충하고 강력한 교전 능력을 갖추세요. 신발은 카밀의 기본 공격 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 점화를 추천해요. 점화로 카밀의 (W)\'전술적 휩쓸기\'를 통한 체력 회복을 억제하고 킬각을 잡으세요.' },
    '카사딘': { lv1: '카사딘의 (Q)\'무의 구체\'로 인한 보호막을 고려하며 무리하게 진입하지 마세요. (Q)\'야수의 송곳니\'를 활용해 체력을 회복하며 미니언을 챙기는 것이 좋아요. 상대의 견제를 받으면서 피 관리를 철저히 하며 맞딜 준비를 해요.', lv3: '카사딘의 (E)\'힘의 파동\' 둔화에 걸리지 않도록 주의하며 거리를 조절하세요. (E)\'원시의 포효\'를 사용하여 상대의 접근을 막거나 공포를 활용해 딜교환을 시도해요. (Q)\'야수의 송곳니\'를 맞히며 적의 보호막이 빠진 타이밍에 붙어야 해요.', lv6: '카사딘이 (R)\'균열 이동\'으로 도망가지 못하도록 (R)\'무한의 구속\'을 신중하게 사용하세요. 상대의 체력이 낮을 때 (W)\'피의 사냥\' 효과를 받으며 적극적으로 추격해요. 라인을 적절히 당겨서 정글러의 개입을 유도하며 압박을 이어가세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 구매하세요. 카사딘의 마법 피해를 견디고 전투 지속력을 높이기 위해서예요.', spell: '점멸과 유체화를 추천해요. (R)\'균열 이동\'으로 도망가는 카사딘을 추격하거나 거리를 벌리기 좋아요.' },
    '카시오페아': { lv1: '1~2레벨에는 (Q)\'맹독 폭발\'로 인한 독 중독을 조심하며 거리를 유지해요. (Q)\'야수의 송곳니\'로 미니언을 챙기며 체력을 관리하고 상대의 공격을 받아내세요. (P)\'끝없는 허기\' 패시브 덕분에 체력이 낮아져도 회복할 수 있으니 차분하게 대응해요.', lv3: '3레벨 이후에는 카시오페아가 (W)\'독기의 늪\'을 깔아 (Q)\'야수의 송곳니\'를 못 쓰게 만드는 것을 조심하세요. (E)\'원시의 포효\'를 사용해 피해를 줄이면서 카시오페아의 (E)\'쌍독니\' 타이밍에 맞춰 진입해요. (E)\'원시의 포효\'의 공포를 활용해 딜교환을 마무리하세요.', lv6: '6레벨에는 (R)\'무한의 구속\'으로 카시오페아를 제압하며 킬을 노려보세요. (R)\'석화의 응시\'는 카시오페아를 바라보는 적을 기절시키니 궁극기를 쓰는 모습이 보이면 등을 돌리세요. 상대의 체력이 낮아지면 빠르게 접근하여 승부를 보세요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 가세요. 상대의 마법 피해에 저항하고 체력이 낮을 때 보호막을 얻어 생존력을 높여줘요.', spell: '점멸과 점화를 추천해요. (R)\'무한의 구속\'으로 상대를 잡은 뒤 점화를 쓰면 (E)\'쌍독니\' 회복을 줄이며 확실하게 처치할 수 있어요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'을 던져 (P)\'폭풍의 표식\'을 쌓으며 견제하니, 수리검을 옆으로 피해 표식이 쌓여 기절하는 상황을 피하세요. 틈이 보이면 (Q)\'야수의 송곳니\'로 빠르게 붙어 기본 공격을 섞어 체력을 깎아내세요. 무리하게 들어가기보다 체력 관리를 하며 진입 시점을 잡으세요.', lv3: '케넨이 (E)\'번개 질주\'로 진입해 표식을 남기려 하면 (E)\'원시의 포효\'를 켜서 받는 피해를 줄이세요. (W)\'전류 방출\'로 기절이 걸리기 직전에 (E)\'원시의 포효\'를 재사용해 공포를 걸어 케넨의 흐름을 끊으세요. (Q)\'야수의 송곳니\'를 길게 눌러 케넨이 이동하는 방향을 따라가며 물고 늘어지세요.', lv6: '케넨이 (R)\'날카로운 소용돌이\'를 사용하면 주변에 반복 피해를 주니 범위 안에서 오래 버티지 말고 즉시 거리를 벌리세요. 소용돌이가 끝난 직후 (R)\'무한의 구속\'으로 도약해 제압하면 케넨이 (E)\'번개 질주\'로 빠져나가기 전에 몰아칠 수 있어요. (W)\'피의 사냥\'으로 이동 속도를 높여 정글러와 함께 순식간에 거리를 좁히세요.', item: '삼위일체를 첫 코어로 가서 공격 속도와 체력을 보충하고 강력한 평타 딜교환을 하세요. 신발은 케넨의 마법 피해를 줄이고 기절 시간을 단축하는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화로 (E)\'번개 질주\'를 사용해 거리를 벌리는 케넨을 끝까지 추격할 수 있어요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\'이 쌓이기 전인 초반에 공격 속도와 사거리가 아직 낮아요. 케일이 미니언을 챙기려 다가올 때 (Q)\'야수의 송곳니\'로 빠르게 접근해서 압박하세요. 이 구간에 짧은 딜교환을 이어가며 케일의 성장을 늦추세요.', lv3: '케일이 (Q)\'광휘의 일격\'을 사용해 이동 속도와 방어력을 낮추려 할 때 (E)\'원시의 포효\'로 들어오는 피해를 줄이며 다가가세요. (E)\'화염주문검\'은 대상의 잃은 체력에 비례해 피해를 주므로 체력이 낮을 때는 딜교환을 피해야 해요. 케일의 스킬이 빠지면 (Q)\'야수의 송곳니\'로 물어서 압박하세요.', lv6: '케일이 (R)\'신성한 심판\'을 사용해 무적 상태가 되면 (R)\'무한의 구속\'의 제압 효과를 줄 수 없으니 주의하세요. 케일의 무적이 끝나는 타이밍에 맞춰서 (R)\'무한의 구속\'을 사용해야 확실한 킬각을 잡을 수 있어요. 라인을 밀어 넣으며 정글러의 개입을 유도해 보세요.', item: '케일의 마법 피해를 견디기 위해 헤르메스의 발걸음을 신으세요. 코어 아이템으로는 전투 지속력을 높여주는 갈라진 하늘을 추천해요.', spell: '점멸과 점화를 추천해요. 케일이 성장하기 전에 점화로 체력 회복을 억제하며 킬을 노려보세요.' },
    '코그모': { lv1: '첫 웨이브를 받아먹으며 코그모의 (Q)\'부식성 침\' 견제를 피하기 위해 미니언을 활용하세요. (E)\'공허의 분비물\'이 남긴 바닥에 닿지 않게 주의하며 (Q)\'야수의 송곳니\'를 쓸 타이밍을 봐요.', lv3: '코그모의 (W)\'생체마법 폭격\'을 먼저 빼도록 유도하며 거리를 조절하세요. (E)\'원시의 포효\'로 피해를 줄이며 (Q)\'야수의 송곳니\'로 진입하여 딜교환을 이어가면 편해요.', lv6: '코그모의 체력이 낮으면 (R)\'무한의 구속\'으로 제압하여 킬을 노려보세요. (R)\'살아있는 곡사포\'에 맞으면 위치가 드러나 상대 정글러가 노리기 쉬우니 라인을 당겨 두세요. (E)\'원시의 포효\'로 코그모의 마법 피해를 버티며 싸우세요.', item: '코그모의 마법 피해를 견디기 위해 헤르메스의 발걸음을 선택해요. 전투 지속력을 높이려고 몰락한 왕의 검을 첫 코어 아이템으로 가요.', spell: '점멸과 유체화를 추천해요. 거리를 좁히고 코그모를 추격하기 위해서예요.' },
    '코르키': { lv1: '코르키의 (Q)\'인광탄\' 견제를 피하며 미니언을 챙겨야 해요. (E)\'원시의 포효\'를 사용하여 상대의 초반 피해를 줄이면서 거리를 조절하세요. 무리하게 진입하기보다 체력을 관리하며 기회를 기다려요.', lv3: '(Q)\'야수의 송곳니\'를 사용하여 코르키에게 빠르게 접근하며 딜교환을 시도해요. 코르키가 (E)\'개틀링 건\'을 사용하기 전에 (E)\'원시의 포효\'를 켜서 피해를 줄이는 것이 중요해요. (Q)\'야수의 송곳니\'로 적을 물면 입힌 피해만큼 체력을 회복하며 버틸 수 있어요.', lv6: '(R)\'무한의 구속\'으로 코르키를 제압하고 집중적으로 공격하여 킬을 노려요. 코르키가 (R)\'미사일 폭격\'을 사용하며 저항할 수 있으니 접근 시 주의해야 해요. 정글러가 근처에 있다면 (R)\'무한의 구속\'으로 적을 묶어 킬을 만들어내요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 추천해요. 코르키의 마법 피해를 견디고 생명선 효과로 생존력을 높이기 위해서예요.', spell: '점멸과 점화를 추천해요. 점멸로 코르키에게 거리를 좁히고, 점화로 마무리 피해를 넣어 확실하게 처치하세요.' },
    '퀸': { lv1: '퀸은 (Q)\'실명 공격\'으로 시야를 좁히고 (P)\'매사냥\' 표식을 통해 강한 평타 견제를 해요. (Q)\'야수의 송곳니\'로 진입하려 하면 (E)\'공중제비\'로 거리를 벌리니, 상대의 돌진기가 빠진 타이밍을 노리세요. 초반에는 체력이 낮아질 때까지 버티며 (P)\'끝없는 허기\'의 회복력을 믿고 끈질기게 붙으세요.', lv3: '(W)\'피의 사냥\'으로 이동 속도를 높여 접근하고, 퀸이 (E)\'공중제비\'로 밀어내기 전에 (E)\'원시의 포효\'를 켜서 피해를 줄이세요. 포효의 공포 효과로 퀸의 스킬 연계를 끊고, 그 틈에 (Q)\'야수의 송곳니\'로 다시 물고 늘어지세요. 퀸이 (W)\'예리한 감각\'으로 얻은 가속을 이용해 도망가기 전에 빠르게 딜교환을 마치세요.', lv6: '(R)\'무한의 구속\'은 이동 속도에 비례해 먼 거리를 도약하므로, (W)\'피의 사냥\'과 함께 사용해 도망가는 퀸을 제압하세요. 퀸이 (R)\'후방 지원\'을 사용해 빠르게 날아다닐 때는 무리하게 쫓지 말고, 강습으로 내려오는 지점을 예측해 대응하세요. 라인을 밀어 넣고 정글러를 부르면 (E)\'공중제비\' 한 번으로는 빠져나가기 힘들어요.', item: '몰락한 왕의 검을 첫 코어로 가서 공격 속도와 생명력 흡수로 끈질기게 추격하세요. 신발은 퀸의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화로 퀸의 거리 조절을 무력화하고 끝까지 따라가서 물 수 있어요.' },
    '크산테': { lv1: '크산테가 (Q)\'엔토포 타격\'으로 견제하며 중첩을 쌓으려 하니 너무 멀리 있지 마세요. 1~2레벨 구간은 (P)\'끝없는 허기\' 회복을 믿고 평타를 섞으며 압박하세요. 미니언을 사이에 두고 크산테의 첫 타격을 피하며 체력을 관리하는 것이 중요해요.', lv3: '크산테가 (E)\'발놀림\'으로 보호막을 얻으며 다가오면 (Q)\'야수의 송곳니\'로 맞대응하여 체력을 회복하세요. (W)\'길을 여는 자\'의 저지 불가 돌진은 막을 수 없으니 충전 모습이 보이면 옆으로 피해 주세요. (Q)\'엔토포 타격\'의 두 번째 충격파가 발동되기 전에 거리를 조절하세요.', lv6: '크산테가 (R)\'총공세\'를 사용하면 방어력이 낮아지니 (R)\'무한의 구속\'으로 제압하여 빠르게 몰아치세요. 크산테가 벽 너머로 밀어내려 하니 정글러의 개입을 조심하며 (E)\'원시의 포효\'를 적절히 사용하여 대응하세요. 크산테의 변신 후 강력한 피해를 버티기 위해 체력 관리에 유의해야 해요.', item: '몰락한 왕의 검을 첫 코어로 가서 지속 전투력을 높이세요. 신발은 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화를 사용하여 크산테의 체력 회복을 억제하고 킬을 노리세요.' },
    '클레드': { lv1: '클레드는 (Q)\'덫날리기\'로 적을 끌어당기며 1~2레벨에 강한 모습을 보여요. (Q)\'덫날리기\'를 맞고 클레드 근처에 머물면 끌려가며 피해를 입으니 거리를 조절하세요. (Q)\'야수의 송곳니\'를 사용해 클레드의 체력을 깎으며 체력 회복을 노려보세요.', lv3: '클레드가 (E)\'이랴!\'로 돌진하며 다가올 때 (E)\'원시의 포효\'를 사용해 피해를 줄이고 공포를 걸어 대응하세요. (W)\'버럭버럭\'으로 공격 속도가 빨라진 클레드와는 긴 평타 싸움을 피해야 해요. (Q)\'야수의 송곳니\'로 적중시키며 (W)\'피의 사냥\' 효과로 이동 속도를 얻어 활용하세요.', lv6: '클레드가 (R)\'돌겨어어억!!!\'으로 보호막을 얻고 돌진해 오면 일직선상에서 벗어나세요. 클레드가 스칼에서 내려 체력이 낮을 때 (R)\'무한의 구속\'으로 제압하면 큰 피해를 주고 체력을 회복할 수 있어요. 라인을 당겨서 클레드의 돌진을 유도하며 정글러의 도움을 받으세요.', item: '첫 코어로 몰락한 왕의 검을 가서 전투 지속력을 높이세요. 신발은 클레드의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 스칼에서 내린 클레드는 챔피언에게 주는 피해가 줄어드니 이때 점화의 지속 고정 피해로 빠르게 마무리하세요.' },
    '탐켄치': { lv1: '탐 켄치가 (Q)\'혀 채찍\'으로 견제하며 (P)\'절대 미각\' 중첩을 쌓으려 하니 평타 교환은 짧게 하세요. (Q)\'혀 채찍\'은 처음 맞는 유닛에게 피해를 주니 미니언을 사이에 두고 거리 조절을 하며 (Q)\'야수의 송곳니\'로 진입 타이밍을 보세요. 중첩이 가득 차 기절하지 않도록 주의하며 전투를 이어가세요.', lv3: '탐 켄치가 (E)\'두꺼운 피부\'를 사용해 비축한 피해를 보호막으로 바꾸면 딜이 흡수되니 보호막이 사라진 뒤에 (Q)\'야수의 송곳니\'를 쓰세요. (W)\'심연 잠수\'가 사용되면 범위 내에서 공중으로 뜨니 주의하고, (E)\'원시의 포효\'로 피해를 줄이며 맞딜을 하세요. (P)\'절대 미각\' 중첩이 쌓이지 않게 조심하며 (Q)\'야수의 송곳니\'로 피해를 입히세요.', lv6: '탐 켄치가 (R)\'집어삼키기\'를 사용하기 전에 (R)\'무한의 구속\'으로 먼저 제압하는 것이 좋아요. (E)\'두꺼운 피부\' 보호막이 켜진 상태에서는 딜이 흡수되니 보호막이 사라진 다음까지 기다리세요. 체력이 낮을 때 탐 켄치가 삼키기를 쓰면 위험하니 라인 관리와 함께 정글러의 개입을 요청하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 공격 속도와 생명력 흡수를 챙기세요. 신발은 탐 켄치의 마법 피해를 줄이는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 탐 켄치의 (Q)\'혀 채찍\' 회복 효과를 줄이세요.' },
    '트런들': { lv1: '트런들은 (Q)\'깨물기\'로 공격력을 흡수하며 1~2레벨 평타 교환이 강해요. (Q)\'깨물기\'에 맞으면 공격력이 낮아지니 (Q)\'야수의 송곳니\'로 짧게 치고 빠지는 것이 좋아요. 트런들은 (P)\'헌납\'으로 주변 유닛이 쓰러질 때마다 체력을 회복하니 미니언이 많은 곳에서 싸우지 마세요.', lv3: '트런들이 (W)\'얼음 왕국\'을 사용하면 공격 속도와 치유 효과가 늘어나니 영역 밖에서 싸우세요. (E)\'얼음 기둥\'은 지나갈 수 없는 벽이라 경로를 막고 주변을 둔화시키니 기둥 위치를 확인하고 돌아가세요. 트런들이 붙을 때 (E)\'원시의 포효\'로 피해를 줄이며 공포로 흐름을 끊으세요.', lv6: '트런들이 (R)\'진압\'을 사용하면 체력과 방어력을 훔쳐가니 스킬이 빠진 것을 확인하고 (R)\'무한의 구속\'으로 제압하세요. (R)\'진압\'으로 훔친 능력치가 사라질 때까지 거리를 벌리며 (E)\'원시의 포효\'로 트런들의 진입을 방해하세요. 트런들은 근처에서 적이 쓰러질 때마다 회복하니 라인 관리에 유의하며 정글러의 도움을 기다리세요.', item: '몰락한 왕의 검을 첫 코어로 가서 체력 회복과 공격 속도를 챙기세요. 신발은 트런들의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 트런들의 (P)\'헌납\'과 (W)\'얼음 왕국\' 회복을 억제하며 싸우세요.' },
    '트린다미어': { lv1: '트린다미어는 (P)\'격노\'로 분노를 쌓아 치명타 확률을 높이고 (Q)\'피의 갈망\'으로 체력을 회복해요. 체력이 낮은 트린다미어를 무시하고 덤비면 위험하니 거리를 조절하며 (Q)\'야수의 송곳니\'로 짧게 체력을 회복하세요. 첫 웨이브는 평타 교환을 최소화하며 상대의 분노 수치를 확인하세요.', lv3: '트린다미어가 (E)\'회전 베기\'로 들어올 때 (E)\'원시의 포효\'를 켜서 받는 피해를 줄이고 공포로 밀어내세요. (W)\'조롱의 외침\'을 맞고 등을 돌리면 이동 속도가 느려지니 정면에서 (Q)\'야수의 송곳니\'로 대응하며 맞서세요. 상대의 (E)\'회전 베기\'가 빠진 타이밍에 공격적으로 딜교환을 시도하세요.', lv6: '(R)\'불사의 분노\'가 켜진 동안에는 체력이 줄어들지 않으니 (R)\'무한의 구속\'으로 제압하며 시간을 끄세요. 불사 지속 시간이 끝나는 순간이 가장 좋은 킬각이니 그때 모든 피해를 쏟아부으세요. 라인 관리 중 트린다미어가 무리하게 들어오면 (E)\'원시의 포효\'로 버티며 정글의 도움을 기다리세요.', item: '판금 장화와 몰락한 왕의 검을 추천해요. 판금 장화는 기본 공격 피해를 줄여주고 몰락한 왕의 검은 생명력 흡수와 공격 속도로 트린다미어를 압도하게 도와줘요.', spell: '점멸과 점화를 추천해요. 트린다미어가 (Q)\'피의 갈망\'으로 체력을 회복하는 것을 점화의 치유 감소 효과로 억제하세요.' },
    '티모': { lv1: '1~2레벨 구간에서는 티모가 (Q)\'실명 다트\'로 시야를 가리고 (E)\'맹독 다트\'로 피해를 주며 강해요. (P)\'유격 전투\'로 숨어있을 수 있으니 수풀 근처에서 시야를 항상 확인하세요. 실명 상태에서는 평타 교환이 어려우니 무리하게 붙지 마세요.', lv3: '티모의 (Q)\'실명 다트\'가 빠진 타이밍에 (Q)\'야수의 송곳니\'로 도약해 진입하세요. (E)\'원시의 포효\'를 사용해 피해를 견뎌내며 (W)\'피의 사냥\'의 이동 속도로 거리를 좁히세요. 티모가 (W)\'신속한 이동\'을 사용해 도망가더라도 끝까지 추격하세요.', lv6: '(R)\'유독성 함정\'은 밟으면 이동 속도가 늦춰지니 길목에 깔린 버섯을 잘 피하며 이동하세요. (R)\'무한의 구속\'으로 티모를 제압한 뒤 (Q)\'야수의 송곳니\'를 연계해 확실하게 킬각을 잡으세요. 티모가 버섯을 이용해 도망갈 수 있으니 라인 관리에 신경 쓰세요.', item: '맬모셔스의 아귀를 첫 코어로 가서 마법 저항력을 높이고 생명선을 얻으세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음을 신으세요.', spell: '점멸과 유체화를 추천해요. 유체화로 (W)\'신속한 이동\'을 사용하는 티모의 움직임을 따라잡기 좋아요.' },
    '판테온': { lv1: '판테온은 (Q)\'혜성의 창\'으로 멀리서 견제하며 1~2레벨 구간에 강한 모습을 보여요. (Q)\'혜성의 창\'의 사거리를 조심하며 미니언을 챙기고, 판테온이 (W)\'방호의 도약\'으로 들어오면 (E)\'원시의 포효\'를 사용하여 피해를 줄이세요.', lv3: '판테온의 (W)\'방호의 도약\' 기절을 조심해야 하며, 이 스킬이 빠진 것을 확인한 뒤 (Q)\'야수의 송곳니\'로 거리를 좁히세요. (E)\'방패 돌격\'을 사용한 판테온은 정면 공격에 무적이니 옆으로 돌아가서 공격하는 것이 좋아요.', lv6: '판테온이 (R)\'거대 유성\'으로 다른 라인에 가면 라인을 밀어 포탑을 압박하고, 돌아온 뒤 (W)\'방호의 도약\'이 빠졌을 때 (R)\'무한의 구속\'으로 제압하세요. 판테온이 (R)\'거대 유성\'으로 들어올 때 (E)\'원시의 포효\'를 미리 사용하면 피해를 줄이면서 대응할 수 있어요.', item: '판테온의 기본 공격 피해를 줄여주는 판금 장화를 추천해요. 첫 코어 아이템으로는 생명력 흡수 효과가 있는 몰락한 왕의 검이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 판테온의 체력을 빠르게 깎아 킬을 만들어보세요.' },
    '피들스틱': { lv1: '피들스틱이 시야 밖에서 (Q)\'공포\'를 사용하여 기습하는 것을 경계하며 미니언을 챙기세요. (Q)\'야수의 송곳니\'로 무리하게 들어가기보다 거리를 유지하며 체력을 보존해야 해요. 상대의 위치를 계속 확인하며 (E)\'원시의 포효\'를 사용할 준비를 하세요.', lv3: '피들스틱이 (W)\'풍작\'을 사용하며 체력을 흡수할 때 (E)\'원시의 포효\'로 공포를 걸어 흐름을 끊으세요. (E)\'수확\'의 중심부에 맞아 침묵에 걸리지 않도록 주의하며 (Q)\'야수의 송곳니\'로 접근해야 해요. (E)\'원시의 포효\'를 활용해 피해를 줄이며 딜교환을 시도하세요.', lv6: '피들스틱이 (R)\'까마귀 폭풍\'을 사용해 기습하지 못하도록 와드로 시야를 확보하는 것이 중요해요. (R)\'무한의 구속\'으로 상대를 제압하면 강력한 피해를 입히며 킬을 노릴 수 있어요. 라인을 빠르게 밀어 상대가 매복할 공간을 줄이며 정글러를 부르세요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 가세요. 헤르메스의 발걸음은 마법 저항력과 강인함을 제공하고 맬모셔스의 아귀는 마법 저항력과 생명선 보호막을 줘요.', spell: '점멸과 점화를 사용하세요. 점멸은 거리를 좁히거나 (Q)\'공포\'를 피할 때 쓰고 점화는 상대를 빠르게 처치하는 데 도움을 줘요.' },
    '피오라': { lv1: '피오라가 (Q)\'찌르기\'로 진입하며 (P)\'치명적인 검무\'의 급소를 노리니 급소 방향을 피해 움직이세요. 1~2레벨에는 평타 위주로 대응하며 상대가 (E)\'대가의 검술\'로 둔화를 걸고 치명타를 입히는 것을 조심하세요. (P)\'끝없는 허기\'의 회복력을 믿고 짧게 교전한 뒤 물러나세요.', lv3: '피오라가 (W)\'응수\'를 켜면 모든 공격과 이동 불가 효과를 막으므로 (Q)\'야수의 송곳니\'나 (E)\'원시의 포효\'의 공포 효과를 사용하지 말고 기다리세요. (W)\'응수\'가 빠진 것을 확인한 뒤 (Q)\'야수의 송곳니\'로 진입해 체력을 회복하며 싸우세요. (E)\'원시의 포효\'의 피해 감소 효과를 사용해 피오라의 (E)\'대가의 검술\' 치명타 피해를 줄이세요.', lv6: '(R)\'무한의 구속\'은 (W)\'응수\'에 막히면 기절하므로 피오라의 (W)\'응수\'가 빠진 시점에 정확히 사용하세요. (R)\'대결투\'가 시작되면 급소를 계속 피해 움직이며 (E)\'원시의 포효\'로 버티다가 (Q)\'야수의 송곳니\'로 체력을 회복하세요. 라인 관리를 통해 정글러를 부르거나 포탑 근처에서 짧게 교전하며 피오라의 (R)\'대결투\' 회복을 방해하세요.', item: '삼위일체를 첫 코어로 선택해 공격력과 체력을 높이고 딜교환 능력을 키우세요. 신발은 피오라의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 피오라가 (P)\'치명적인 검무\'와 (R)\'대결투\'로 체력을 회복하는 것을 점화의 치유 감소 효과로 억제하세요.' },
    '하이머딩거': { lv1: '하이머딩거는 (Q)\'H-28 G 진화형 포탑\'을 설치해 라인을 장악해요. 포탑 근처에서 오래 싸우지 말고 (Q)\'야수의 송곳니\'로 하이머딩거만 노려 짧게 교환하세요. 포탑이 빠진 틈에 차분히 미니언을 챙기세요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'은 중앙에 맞으면 기절하니 거리를 조절하며 상대의 스킬을 빼세요. 스킬이 빠지면 (E)\'원시의 포효\'를 사용하여 피해를 줄이며 (Q)\'야수의 송곳니\'로 파고드세요.', lv6: '하이머딩거가 (R)\'업그레이드!!!\'로 강화된 포탑을 설치하면 잠시 뒤로 물러나서 기다리세요. 강화된 포탑이 사라진 뒤 (R)\'무한의 구속\'으로 하이머딩거를 제압하며 몰아붙이세요. 라인을 밀어 넣은 뒤에는 정글러의 개입을 유도하며 압박하세요.', item: '마법 피해를 견디기 위해 헤르메스의 발걸음을 구매하세요. 첫 코어 아이템은 몰락한 왕의 검을 선택하여 전투 지속력을 높이세요.', spell: '점멸과 점화를 추천해요. (R)\'무한의 구속\'으로 하이머딩거를 붙잡았을 때 점화로 확실하게 처치하세요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_warwick);
if (typeof module !== 'undefined') module.exports = top_warwick;
